-- GENERATED by `wfj generate` from data/quest/quest-0092.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [92008] = { "Pezzi di prima scelta", "Ritira l'ordine di pezzi di Kaylaena Sussurrafonte da Nami a ⟦Everlook=Lungavista⟧.", "Un altro volto nuovo?\n\nNon dovrei sorprendermi, vista la forza delle nostre cosiddette difese di questi tempi. Com'è il vile, laggiù? Non esco da questa officina da settimane. Senti, già che sei qui, ho alcuni favori per cui potresti darmi una mano, se ti va di fare commissioni.\n\nNon crederesti quanto sia difficile procurarsi i pezzi giusti fin quassù, per non parlare del materiale da costruzione generico per l'ingegneria. Nami a ⟦Everlook=Lungavista⟧ ha un ordine di pezzi che mi aspetta: ti va una corsa invernale?", nil, nil, 0x904d71ae, 0x7448aa80, 0x4c5ace7c, nil, nil, "...mm" },
  [92009] = { "La cassa delle aspettative", "Trasporta con cautela la cassa di pezzi e ninnoli a Kaylaena Sussurrafonte sul ⟦Mount Hyjal=Monte Hyjal⟧.", "C'è una cosa che dovresti sapere su questo ordine. Sul fondo della scatola ci sono alcune celle di mana invertite, imbottite come meglio ho potuto. Le celle tendono a scaricarsi se vengono urtate e se non vengono stabilizzate in tempo. Ci vogliono circa due ore perché il contenuto si esaurisca.\n\nKaylaena saprà cosa fare quando le riceverà, ma ti suggerisco di andare piano se hai intenzione di cavalcare sul ⟦Mount Hyjal=Monte Hyjal⟧.\n\nSe ti serve una ricarica, torna e rabboccherò i contenitori. Fa' attenzione, d'accordo?", nil, nil, 0x66487fff, 0x504f2f74, 0x65b200b2, nil, nil, "...mm" },
  [92011] = { "Frugare tra le macerie", "Recupera quel che resta della base dell'⟦Horde=Orda⟧ e riporta a Kaylaena $N1 Filo Sfilacciato, $N2 ⟦Scrap Metal=Pezzo di Metallo⟧ e $N3 Escrementi Calcificati.", "Mi servirà un po' di tempo per decidere quali progetti costruire per primi. Una cosa che avevo in mente di fare è arrampicarmi fino alla vecchia base dell'⟦Horde=Orda⟧ e vedere che tipo di tesori si possono ricavare da qualunque rifiuto sia rimasto lì.\n\nSe ci vai, e hai spazio per portarlo, tieni gli occhi aperti per rottami metallici, fili o pezzi di... escrementi di pipistrello! Guarda, ha i suoi usi, ok!\n\nTroverai i resti dell'accampamento dell'⟦Horde=Orda⟧ in alto sulla montagna, persino oltre l'insediamento della Selva Antica.", nil, nil, 0x38751759, 0xfb1b8c43, 0x31d4128d, nil, nil, "...mm" },
  [92014] = { "Tana di volpe", "Riporta $N1 Coda di Volpe Fogliaruggine a Johun \"Cazzotto\" Dillas a Hyjal.", "Ogni volta che distolgo l'attenzione dalle provviste che ho trascinato quassù per più di qualche minuto, uno dei migliori ladri della natura le sta rubando e rovistando.\n\nQuelle maledette volpi sembrano aver fatto una tana sotto i massi qui vicino. A quanto pare, il mio scavare questa buca ha dato loro un'idea.\n\nSto lavorando a una soluzione. Ti dico cosa: portami alcune delle loro code di volpe. Servirà loro da lezione e appenderò le code lungo il perimetro per spaventare le altre!", nil, nil, 0x2402a44c, 0xdfd81f26, 0x72380006, nil, nil, "...mm" },
  [92015] = { "Puzzole di sbarramento", "Fai allontanare le puzzole dall'area intorno all'attrezzatura di Johun senza ucciderle.", "Dici di voler aiutare? Va bene, ho un compito per te.\n\nTi è mai capitato di essere spruzzato da una puzzola in una giornata calda? Non c'è niente di peggio, te lo assicuro. Quelle maledette cose ricoprono tutto nel raggio di uno sputo del più disgustoso e persistente fetore!\n\nUna famiglia di puzzole ha iniziato a farsi la tana dietro le mie casse di attrezzatura. Aiutami a scacciarle con delicatezza dal nostro perimetro e penserò di condividere un po' di questo equipaggiamento, una volta che ci arriveremo...\n\nNon mi stancherò mai di ripeterlo: non attaccarle, TI SPRUZZERANNO!", nil, nil, 0xe7213fd9, 0x69b74432, 0xf1e7ad37, nil, nil, "...mm" },
  [92016] = { "Lavoro sulle radici", "Entra nel ⟦Well of Eternity=Pozzo dell'Eternità⟧ ed esamina le radici di Nordrassil.", "Le radici di Nordrassil si estendono lontano e in profondità, più spesse di rive di fiume e più antiche della memoria. Una tale grandezza porta con sé una grande fame. Nei tempi sani, bevono tanto dalla decomposizione quanto dal rinnovamento, traendo forza dall'incessante ruotare del ciclo naturale.\n\nMa Hyjal è stata ferita, il suo suolo contaminato dal veleno demoniaco.\n\nDiscendi nelle profondità più remote del ⟦Well of Eternity=Pozzo dell'Eternità⟧. Studia da vicino le radici laggiù. Dobbiamo sapere se hanno assorbito troppa corruzione... o se l'Albero del Mondo potrà ancora resistere.", nil, nil, 0xae7a31f8, 0xf6de32c6, 0x703d6363, nil, nil, "...mm" },
  [92017] = { "Venti purificatori", "Raccogli $N1 Grande Piuma di Ippogrifo e $N2 Pelo di Chimera Oleoso per Marn.", "Le creature volanti della Vetta respirano ancora dalle correnti più alte, dove la corruzione non ha ancora preso del tutto piede. Piume d'ippogrifo e peli di chimera fluttuano in questi venti, assorbendo ciò che l'aria ricorda di una terra incontaminata. Mi servono questi resti per ancorare e rafforzare il mio incenso purificatore.\n\nRaccoglili per me, così potrò concentrare la conoscenza del vento in un fumo purificatore prima di iniziare il rituale.", nil, nil, 0xa62bf995, 0x222c73a8, 0x77603cd9, nil, nil, "...mm" },
  [92020] = { "Il Grande Libro delle Grandi Lucertole di Hol'anyee", "Porta il Grande Libro delle Grandi Lucertole di Hol'anyee a un druido sulla vetta del ⟦Mount Hyjal=Monte Hyjal⟧.", "Ho preso appunti e fatto disegni nei miei album di tutte le creature che vivono nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧, e ne ho fatto qualche copia da inviare a chi potrebbe esserne interessato!\n\nHo qui una copia di un album che volevo far arrivare nelle mani dei druidi del ⟦Mount Hyjal=Monte Hyjal⟧, dato che so che amano studiare il mondo naturale.\n\nHyjal è un po' lontano, però. Pensi di poterla portare con te, nel caso ci andassi?", nil, nil, 0xdf1685da, 0x2b346bda, 0x3e887c61, nil, nil, "...mm" },
  [92064] = { "Liberare l'albero", "Spezza il ramo dell'albero per liberare Fenwick Mollascatto.", "Proviamo qualcos'altro. Vedi quel ramo lassù? Sì! Quello. Mi serve che tu me lo spezzi. Ho un sacco di corde annodate altrove, quindi non c'è rischio di un cedimento catastrofico... spero.\n\nFai un passo indietro, al sicuro, e dai qualche colpo a questo ramo, ti va?\n\n<Fenwick indica qualcosa sopra la sua testa.>\n\nTi prego, fa' attenzione!", nil, nil, 0x24a51cf6, 0x7a07d3a8, 0x42395080, nil, nil, "...mm" },
  [92065] = { "Bonifica degli Zannanera", "Porta la testa di Varrox Zoccolotetro al ⟦Gatekeeper Rageroar=Custode del Portale Gridoatroce⟧ a Ursolan.", "Ci aiuterai nella nostra battaglia finale, {race}, e sarai la salvezza degli Zannanera?\n\nVarrox Zoccolotetro, flagello degli Zannanera: un demone la cui fame di distruzione non sarà mai saziata. La sua corruzione consuma tutto ciò che tocca. Anche ora, lui e i suoi sottoposti continuano a devastare le nostre tane.\n\nAbbiamo fatto molta strada nella nostra lotta contro i Legashi, ma perché gli Zannanera abbiano mai un futuro, Varrox deve cadere.\n\nTrovalo nella ⟦Blackmaw Hold=Tana degli Zannanera⟧ e abbattilo. Solo allora gli Zannanera potranno finalmente avere pace.", nil, nil, 0x0ab429e0, 0x52c3221d, 0xa2260c46, nil, nil, "...mm" },
  [92066] = { "Gli orsi gemelli", "Trova il Totem di Ursoc e il Totem di Ursol nella ⟦Blackmaw Hold=Tana degli Zannanera⟧. Poi riportali allo storico Nok a Ursolan.", "Quando i Legashi hanno invaso, molte cose preziose sono state lasciate indietro nella confusione. Di particolare valore per me sono due totem. Raffigurano le leggende dei nostri dèi gemelli, Ursoc e Ursol.\n\nSo che la nostra sopravvivenza immediata è la preoccupazione maggiore, ma dobbiamo anche pensare a salvare la storia del nostro popolo.\n\nQuei totem sono probabilmente ancora nel nostro antico rifugio. Se è così, mi faresti un grande favore a riportarmeli.", nil, nil, 0xdd00ed19, 0xa4c2b366, 0x5c6264d2, nil, nil, "...mm" },
  [92067] = { "L'ora della pappa!", nil, "Ti sei certamente dimostrat<o/a> degn<o/a> ai miei occhi, {name}, ma gli altri della mia tribù sono meno facili da convincere. Per questo dovrai continuare i tuoi sforzi contro i Legashi.\n\nPortami le corna dei satiri Legashi uccisi. Ogni fascio che mi porterai sarà un simbolo del tuo servizio agli Zannanera.", nil, nil, 0x060789f1, nil, 0xb1c3b2ab, nil, nil, ".m.mm" },
  [92069] = { "Artigli che squarciano, zanne che trafiggono", "Porta gli Artigli del Grande Orso e le Zanne dell'Indomito a Ogtinc, ad Azshara.", "Due colossi pattugliano il luogo che gli Zannanera chiamavano casa: Grugnosso l'Indomito e Faucesecca, il grande orso. Generazioni di cacciatori hanno tentato di abbatterli, e tutti hanno fallito.\n\nNon provo gioia nel chiederti di uccidere queste magnifiche bestie, ma il mio popolo deve poter tornare a casa. Il minimo che io possa fare è assicurarmi che la loro morte non sia vana. Se mi porti i loro resti, forgerò un'arma in ricordo della loro forza.", nil, nil, 0xd783ae10, 0x173c4317, 0xfc631c32, nil, nil, "...mm" },
  [92070] = { "Un ricordo perduto", "Trova il proprietario della Collana con Amuleto Piumato.", "La collana è adornata con ciondoli vari: scampoli di piume, gusci di ghianda e sassolini colorati. Il suo laccio di cuoio è strappato. La decorazione suggerisce che appartenesse a un mezzorso, mentre le dimensioni ridotte e la fattura grezza indicano il lavoro di un bambino.\n\nÈ possibile che la collana abbia un valore affettivo per uno degli Zannanera. Potrebbe essere bene trovare il proprietario e restituirla.", nil, nil, 0x5b6695ea, 0x949b50f5, 0xd21d9476, nil, nil, "...mm" },
  [92094] = { "Gnomi razzo", "Wennzut Mollascatto ha perso di vista il fratello Fenwick, che fluttuava con il paracadute verso Hyjal. Cerca dove potrebbe essere finito.", "Mio fratello Fenwick e io abbiamo da poco concluso con successo un test di razzo, l'unico problema è che non è ancora tornato! L'ho perso di vista mentre fluttuava verso sud dopo l'apertura del suo paracadute.\n\nSembra che possa essere atterrato su Hyjal!\n\nSe lo aiuti a trovare la via d'uscita da dove è atterrato, di sicuro troverebbe il modo di ringraziarti. Riavere mio fratello sarebbe una gioia!", nil, nil, 0x1e9e5fb9, 0xa159753e, 0x32373231, nil, nil, "...mm" },
  [92100] = { "Ovunque, tranne qui", "Trova il fodero del Veterano della Terza Guerra vicino alla Selva Antica.", "<Uno spirito si materializza davanti a te, riprendendosi da uno sbadiglio che gli scuote tutto il corpo.>\n\nNon hai gradi con te... e non sei vestit<o/a> da soldato. Quindi abbiamo respinto Archimonde?\n\nÈ passato così tanto tempo. Avevo quasi dimenticato ciò che ero un tempo, ma tu... devi essere una delle prime persone a camminare in questi crateri da anni.\n\n<Il veterano si guarda intorno.>\n\nContinuiamo la nostra conversazione in un punto panoramico che ricordo vividamente, appena a ovest di qui. Molto tempo fa, lasciai lì il mio fodero a riposare.", nil, nil, 0x38562139, 0xc374e791, 0xb6364125, nil, nil, "...mm" },
  [92101] = { "Sollevati dall'eredità", "Trova i segni significativi del Veterano della Terza Guerra sul Grande Ascensore.", "Hyjal è difficile da sopportare. Incubi e ricordi omicidi aleggiano tra i crateri.\n\nMa tu porti con te il calore di Kalimdor! Il mio amico Tobin si è arruolato anche lui ed è partito con me, ma temo il peggio per la sua anima.\n\nLa compagnia dell'⟦Alliance=Alleanza⟧ ci diede dei destrieri da domare e con cui creare un legame in vista del nostro imminente schieramento. Li portammo a fare una cavalcata di piacere per le ⟦Barrens=Savane⟧. Incidemmo i nostri nomi sul fondo del Grande Ascensore a ⟦Thousand Needles=Millepicchi⟧.\n\nVedi se i segni ci sono ancora? Darà sollievo a un'anima stanca.", nil, nil, 0x58e19c88, 0x7492eb2b, 0x6b617fb8, nil, nil, "...mm" },
  [92102] = { "Lode", "Usa il Fodero Ricamato per incontrare il Veterano della Terza Guerra sul ⟦Mount Hyjal=Monte Hyjal⟧, vicino al cannone rotto al Riposo del Lutto.", "Aver fatto tanta strada fuori dal tuo cammino solo per i desideri sbiaditi di un'anima perduta... grazie, {name}. La presenza di una mano che contemplava le incisioni, con i frammenti di storia che conosci finora, è bastata a portarmi qui. La mia presenza, ora, è legata al più forte dei legami con i viventi.\n\nIo sono arrivato alle saline prima di Tobin, e lui mi ha stracciato in pista.\n\nOra ricordo più chiaramente. Incontrami al Riposo del Lutto, il luogo della nostra ultima battaglia, accanto al cannone spezzato vicino alla torre distrutta sulla scogliera.", nil, nil, 0x778df3da, 0x935c01b0, 0xb4ab8106, nil, nil, "...mm" },
  [92109] = { "Il mio primo kit da alchimista", "Porta 5 Empty Vial, 5 Silverleaf e 5 Peacebloom al giovane aspirante alchimista nel fienile di ⟦Moonbrook=Rivoluna⟧, nelle ⟦Westfall=Marche Occidentali⟧.", "Ehm... salve, <signore/signorina>. Non dovrei parlare con gli sconosciuti, ma... Ehi, a cosa servono quelle bottiglie luccicanti che spuntano dal tuo zaino? Fai l'alchimista? Che forte!\n\nDa grande voglio fare l'alchimista anch'io. Papà non mi lascia giocare con le sue erbe: dice che è troppo pericoloso.\n\nBe', io voglio cominciare a imparare adesso. Potresti procurarmi un po' di materiale? Per favore, per favore?", "Ehilà, ancora tu! Hai portato roba di alchimia?", "Oh cielo! Guarda qua! Hai raccolto tu le erbe?\n\nWow, grazie, <signore/signorina>, vado subito a vedere cosa ci posso fare! Vuoi stare a guardare?", 0xea2205a4, 0x2dcf0552, 0x3ea4b9d3, 0x227b486b, 0x1b833324, ".....", nil, nil, 0x543226a7, nil, nil },
  [92110] = { "La mia prima vera pozione", "Raccogli 3 Occhio di Murloc per il giovane aspirante alchimista nel fienile di ⟦Moonbrook=Rivoluna⟧, nelle ⟦Westfall=Marche Occidentali⟧.", "Wow, la mia primissima pozione! Lo sapevi, quando abbiamo cominciato, che mescolando quelle due erbe la pozione sarebbe diventata di un rosso acceso?\n\nÈ stato divertente, ma mescolare qualche fiore non mi sembra il tipo di alchimia che fa papà. Lui usa anche altri ingredienti.\n\nNon so cos'altro usare, quindi proviamo la prima cosa che mi viene in mente! Vediamo... magari occhi di murloc? Che schifo, ma scommetto che succederà qualcosa.", "Non preoccuparti per me, sono una ragazza grande. So badare a me stessa. Solo non dire a nessuno che mi nascondo qui, è il nostro piccolo segreto.", "Mi hai portato gli occhi di murloc! Sono così, così emozionata per la mia prima VERA pozione!\n\nSono sgattaiolata fuori e ho preso qualche altra erba mentre eri via e ho trovato delle fiale vuote di sotto. Ehm... questa volta puoi fare tu il mescolamento.\n\n<La bambina osserva con entusiasmo mentre mescoli gli ingredienti, ma arriccia il naso quando aggiungi gli occhi. L'intruglio assume in pochi secondi un arancione malaticcio.>\n\nWow! Visto, avevo ragione. Io non la berrei, ma ecco la mia ricetta se volessi farne ancora. Torna a trovarmi!", 0x694e0f66, 0x5c5c86d7, 0xcdc27db4, 0x1b57bb4d, 0xc52d73bc, "....." },
  [92111] = { "Di amici e pellicce", "Entra nella Tana dei Pelledura e trova il mezzorso che chiamano Osi.", "Io vedo che tu provi, e provare è più di molti. Noi dare te buona volontà con tempo, se tu fai stesso.\n\nEntra in nostra tana e parla con Osi. Lei ha zampe aperte, darà a te più occasioni di aiutare.", nil, nil, 0xcda7a4ce, 0x2b30cddb, 0xf80a7a62, nil, nil, "...mm" },
  [92124] = { "L'inventario dei libri", "Parla con Daniel, l'assistente di fratello Paxton, nella biblioteca.", "Dobbiamo fare il conto di quanti libri mancano!\n\nVa' a parlare con quell'inetto del mio assistente, Daniel. Può fare un inventario veloce e farci sapere quanto è grave il problema.\n\nÈ fissato con le varie professioni artigiane della ⟦Elwynn Forest=Foresta di Elwynn⟧. Quel ragazzo continua a pensare a quelle invece che al suo importante lavoro, cioè aiutare me.\n\nNon lasciare che si metta a blaterare di professioni, e scopri che fine hanno fatto i miei libri!", nil, "Sì, ho sentito. Ho avvertito fratello Paxton tre volte dei coboldi che scavano gallerie sotto l'abbazia.\n\nPare che i coboldi abbiano preso un sacco di libri. Ci sono interi scaffali svuotati. Faresti meglio a sentire cosa vuole che tu faccia fratello Paxton.\n\nGià che sei qui, posso parlarti delle professioni? Sarei felice di rispondere a qualsiasi domanda o di indicarti gli istruttori della zona.", 0x0231e44e, 0xe64d5a5a, 0x1c2a73d0, nil, 0x9453402b, "...m." },
  [92147] = { "Un aiuto per Piumalta", "Uccidi $N1 arpie Alaverme sul ⟦Mount Hyjal=Monte Hyjal⟧ e porta le loro piume a Phoebe Piumalta.", "Sono tra gli ultimi Piumalta, i veri seguaci di Aviana. Rispettiamo e veneriamo la Matrona dei Cieli, e consideriamo alleati i Druidi dell'Artiglio.\n\nLe arpie Alaverme hanno invaso gran parte di questo altopiano. Rifiutano la nostra protettrice Aviana e cercano solo di devastare le terre intorno a noi.\n\nIl sangue è stato versato e dev'essere ripagato. Disperdi le loro piume al vento.", nil, nil, 0x6e9edde5, 0xed7947ae, 0x9e6069ba, nil, nil, "...mm" },
  [92169] = { "Ripagare il Patto", "Usa il Bastone della Montagna su $N1 membri del Patto di Spinanera sulla Vetta dell'Eternità per rimuovere le loro protezioni, poi uccidili.", "Il Patto di Spinanera. Così si fanno chiamare. Druidi apostati che hanno preso il controllo della Sommità di Hyjal. Violenti ed estremisti. Danno la colpa a ⟦Malfurion Stormrage=Malfurion Grantempesta⟧ di averli privati dell'immortalità e hanno giurato di riprendersi il potere a cui sono stati costretti a rinunciare. Prima non capivo la magia che li potenziava, ma ora sta diventando chiaro.\n\nPrendi il bastone e usalo sui druidi Spinanera sparsi per la montagna. Dovrebbe reagire alle protezioni che li difendono e dissolverle.", nil, nil, 0xf4f5362f, 0xae947170, 0x8bbd0305, nil, nil, "...mm" },
  [92171] = { "Verso nuove altezze", "Recati al Sacrario di Aviana sul ⟦Mount Hyjal=Monte Hyjal⟧ e cerca l'aiuto del Signore del Cielo Omnuron.", "Per sconfiggere Ve'han ci serve un tocco del cielo. Un po' di divino, dove il viso rivolto verso l'alto anela a volare.\n\nVa' al Sacrario di Aviana e cerca il Signore del Cielo Omnuron. Come capo dei Druidi dell'Artiglio, può aiutare ad aggiungere un tocco della grazia di Aviana.", nil, nil, 0xdfb085ca, 0xb712e124, 0xb8f40c01, nil, nil, "...mm" },
  [92189] = { "Di nuovo al lavoro", "Porta $N1 Pietra da Affilatura Densa e $N2 Pietra da Molatura Densa a Trigg Mandiferro nella Selva Antica, sul ⟦Mount Hyjal=Monte Hyjal⟧.", "Och, abbiamo dovuto costruire questo villaggio da zero con quello che siamo riusciti a racimolare dopo la guerra. Tutti i combattimenti hanno messo a dura prova le nostre armi, per non parlare del bisogno di attrezzi!\n\nUn fabbro riconosce sempre un altro fabbro. Pensi di poter dedicare tempo e materiali per farmi delle Pietre da Affilatura Dense e delle Pietre da Molatura Dense? Ci farebbero davvero comodo!", nil, nil, 0x71dcf04e, 0x7ba2e3a2, 0x081717b6, nil, nil, "...mm" },
  [92317] = { "Vita rubata", "Ottieni una Goccia di Vita Rubata dal Flagello nelle rovine sul ⟦Mount Hyjal=Monte Hyjal⟧, poi torna da Ketharas.", "Dunque, il druido eremita cerca una forza che bilanci la 'vita' in questa sua magia? Allora la risposta è la morte, naturalmente. Sei venut<o/a> nel posto giusto per una cosa del genere.\n\nSenza dubbio hai visto i non morti strisciare per tutto il mio dominio. Sono alimentati da un potere rubato che li anima anche nella morte.\n\nQuel potere rubato è esattamente ciò che serve all'incantesimo di cui parli. Uccidi i non morti e cerca nei loro teschi una Goccia di Vita Rubata coagulata. Riportala a Ketharas una volta ottenuta.", nil, nil, 0x56224f2b, 0xaa2aefe5, 0x4ce8a092, nil, nil, "...mm" },
  [92328] = { "L'arte dell'assedio", "Gira i due ingranaggi e collega i due morsetti della batteria su entrambi i lati del Lanciaglaive di Kaylaena.", "Con le scorte extra che hai portato ho abbastanza materiali a disposizione per terminare i piani originali di Yaely per questo Lanciaglaive. Lo sto sistemando da... be', mi sembra da sempre!\n\nSe puoi aiutarmi ed essere un secondo paio di mani, l'intero progetto andrà molto più veloce! Posso guidarti passo passo, quasi tutte le cose difficili dovrebbero essere già a posto...\n\n<Kaylaena incrocia le dita.>\n\nIl sistema di propulsione e le celle energetiche che lo alimentano sono quasi pronti.", nil, nil, 0xf19cd38b, 0x007daef2, 0xe4875c2d, nil, nil, "...mm" },
  [92329] = { "Tamburi di guai", "Cammina fino al crinale a sud dell'officina di Kaylaena e trova un modo per fare un forte baccano che attiri la chimera Ghansurok a portata d'attacco.", "C'è una chimera vile che terrorizza bestie e viaggiatori lungo le colline. È nota al ⟦Cenarion Circle=Circolo Cenariano⟧ come Ghansurok. Io mi occuperò di mirare e sparare con il Lanciaglaive. Vai a quel tamburo vicino al bordo della scogliera. Vediamo di scacciare per sempre questa piaga dalla montagna.\n\nAvrò una possibilità di abbatterla solo se riesci ad attirare la sua attenzione. Quando avrai la bestia vicino alla cresta, cerca un posto dove nasconderti!\n\nSì, ti prometto che ho un sacchetto pieno di semi d'acero!", nil, nil, 0x49e26d57, 0xb0e50a16, 0x587e5ae2, nil, nil, "...mm" },
  [92335] = { "Ceneri dell'ascesa della Legione", "Recupera un pizzico di Ceneri di Azgalor dalle rovine di Dae'gun sul ⟦Mount Hyjal=Monte Hyjal⟧.", "La magia che cerchi è tanto complessa quanto selvaggia. Richiede un reagente che sia fonte stabile di energia continua, e so proprio cosa fa al caso tuo.\n\nQuando Archimonde ha incontrato qui la sua meritata fine, molti dei suoi servitori minori sono stati uccisi. Il suo luogotenente principale, Azgalor, è stato sconfitto, e per mano di mortali come te, per di più!\n\nTroverai gli ultimi resti fisici di Azgalor in mezzo alle rovine qui. Non serve riportare tutta quella cenere a Ketharas. Basta un pizzico per le sue necessità.", nil, nil, 0xa8f328dd, 0xb67f6c13, 0xb5f2d07a, nil, nil, "...mm" },
  [92343] = { "Andare alla radice", "Raccogli 10 Cappello di Radice di Nordrassil nella ⟦Blackmaw Hold=Tana degli Zannanera⟧ per ⟦Nara Wildmane=Nara Manto Selvaggio⟧ al ⟦Thunder Bluff=Picco del Tuono⟧.", "Il cunicolo di cui parli è un tunnel che porta alla ⟦Blackmaw Hold=Tana degli Zannanera⟧. In passato, i mezzorsi l'hanno sorvegliato ferocemente, rendendolo inaccessibile agli estranei. Con la situazione dei satiri, tuttavia, possiamo entrare.\n\nCosì vicino a Nordrassil, ci dovrebbero essere radici in crescita attiva. Radici più vecchie si vedono sulla superficie del mondo, ma quelle più nuove si trovano solo in profondità sottoterra. Poco si sa delle loro proprietà magiche.\n\nSe mi portassi dei campioni da studiare, i druidi di ⟦Thunder Bluff=Picco del Tuono⟧ ti sarebbero debitori.", nil, nil, 0xfa6a61cd, 0x7e73e8df, 0xdc197e84, nil, nil, "...mm" },
  [92344] = { "Andare alla radice", "Raccogli 10 Cappello di Radice di Nordrassil nella ⟦Blackmaw Hold=Tana degli Zannanera⟧ per ⟦Mathrengyl Bearwalker=Mathrengyl Domaorsi⟧ a Darnassus.", "Il cunicolo di cui parli è un tunnel che porta alla ⟦Blackmaw Hold=Tana degli Zannanera⟧. In passato, i mezzorsi l'hanno sorvegliato ferocemente, rendendolo inaccessibile agli estranei. Con la situazione dei satiri, tuttavia, possiamo entrare.\n\nCosì vicino a Nordrassil, ci dovrebbero essere radici in crescita attiva. Radici più vecchie si vedono sulla superficie del mondo, ma quelle più nuove si trovano solo in profondità sottoterra. Poco si sa delle loro proprietà magiche.\n\nSe mi portassi dei campioni da studiare, il ⟦Cenarion Circle=Circolo Cenariano⟧ ti sarebbe debitore.", nil, nil, 0xfa6a61cd, 0x21cee9c4, 0x7c8c37b7, nil, nil, "...mm" },
  [92345] = { "Sotto Nordrassil", "Parla con ⟦Mathrengyl Bearwalker=Mathrengyl Domaorsi⟧ all'⟦Cenarion Enclave=Enclave Cenariana⟧ di Darnassus.", "Forse hai notato i mezzorsi e i satiri a nord di qui che si contendono un cunicolo. Il conflitto non mi interessa quanto ciò che potrebbe esserci dentro. Quel cunicolo sembra condurre sotto Nordrassil.\n\nNon credo di doverti spiegare quanto questo possa interessare i kaldorei.\n\nAbbiamo già il nostro daffare qui, ma i druidi di Darnassus dovrebbero essere informati. Trova ⟦Mathrengyl Bearwalker=Mathrengyl Domaorsi⟧ nell'⟦Cenarion Enclave=Enclave Cenariana⟧. Potrà decidere se vale la pena approfondire.", nil, nil, 0xebe24860, 0xb28a29a5, 0xe0682597, nil, nil, "...mm" },
  [92346] = { "Sotto Nordrassil", "Parla con ⟦Nara Wildmane=Nara Manto Selvaggio⟧ all'⟦Elder Rise=Altura degli Anziani⟧ del ⟦Thunder Bluff=Picco del Tuono⟧.", "Forse hai notato i mezzorsi e i satiri a nordest di qui che si contendono un cunicolo. Il conflitto non mi interessa quanto ciò che c'è dentro. Quel cunicolo sembra condurre sotto l'Albero del Mondo, e chissà cosa potrebbe esserci là sotto?\n\nSiamo troppo sparsi per indagare noi stessi, ma conosco una tauren che potrebbe apprezzare la soffiata. Si chiama ⟦Nara Wildmane=Nara Manto Selvaggio⟧, una druida a ⟦Thunder Bluff=Picco del Tuono⟧. Dille che ti manda Jediga. Fa sempre bene avere qualcuno che ti deve un favore.", nil, nil, 0xebe24860, 0xd3a19168, 0xc2c237aa, nil, nil, "...mm" },
  [92401] = { "Una richiesta spaventata", "Indaga sulla scomparsa di Edward Heartweaver nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧.", "Si tratta di mio marito, Edward...\n\nNon è tornato dal suo viaggio settimanale al cimitero tra le rovine di Lordaeron. Abbiamo perso nostro figlio quando Arthas ha raso al suolo la città, e il mio caro Edward è ancora pieno di colpa e di dolore perché non abbiamo mai trovato il suo corpo. Ho cercato di dissuaderlo dal frugare tra quelle rovine infestate, ma lui non vuole arrendersi. Cerco di non preoccuparmi, ma sono passati giorni.\n\nLaggiù ci sono cose che non posso affrontare, ma se sei dispost<o/a>, ho bisogno di sapere che fine ha fatto mio marito.", nil, "Quello che ti ho chiesto non era giusto, e non sarebbe stato ingiusto se te ne fossi semplicemente andat<o/a>. Grazie, <straniero/straniera>. Non posso ricambiarti come meriti, ma spero che una di queste cose ti sia gradita.\n\nSpero che le nostre strade si incrocino di nuovo senza un simile dolore.", 0xa5170225, 0x5b830c47, 0xd111ed70, nil, 0x35199624, "...m." },
  [92415] = { "Ricorda che ti voglio bene", "Porta la ⟦Blood-Stained Letter=Lettera Macchiata di Sangue⟧ alla matrona degli orfani Usignola, a ⟦Stormwind City=Roccavento⟧.", "<Un fascio di pergamene strappato e macchiato è sopravvissuto a stento al terreno del cimitero, calpestato dai non morti. Parla di un bambino scomparso della famiglia Heartweaver. Forse la direttrice dell'orfanotrofio di ⟦Stormwind City=Roccavento⟧ ne saprà di più.>", "Cosa c'è, {name}? Cosa stai cercando?", "Heartweaver? Heartweaver...\n\nOh! Il piccolo Jeremy Heartweaver. Ce l'hanno portato anni fa, dopo l'attacco a Lordaeron. Ha perso entrambi i genitori nell'attacco, poverino.\n\nA dire il vero, non molto tempo fa è stato adottato da una donna dolcissima di ⟦Duskwood=Boscovespro⟧.", 0x920a601f, 0xab38aea1, 0x10864cbe, 0x093eec87, 0x9c72863a, "....." },
  [92421] = { "La giustizia della Luce", "Raccogli $N1 ⟦Intact Limbs=Arti Intatti⟧ nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ per Morbin Lightbane, a ⟦Undercity=Sepulcra⟧.", "In quanto paladino dei Reietti, è mio dovere eseguire la volontà della nostra Dama Oscura e provvedere ai bisogni della nostra gente. Abbiamo la fortuna di poter fare entrambe le cose.\n\nSopra ⟦Undercity=Sepulcra⟧, il Flagello vaga ancora indisturbato e in gran numero. Le nostre forze si assottigliano nel tentativo di riprenderci la nostra terra, e la carne in decomposizione non si può ricucire. Non senza pezzi di ricambio.\n\nSe il nostro glorioso capitano Garek Bandarion fosse ancora con noi, so cosa vorrebbe: finire ciò che ha cominciato e guarire i nostri simili. Per Lordaeron!", "Cosa resta del Flagello invasore? Sei riuscit<o/a> a trovare pezzi di ricambio adatti?", "Che chi perde la grazia della Regina delle Banshee incontri la nostra giustizia!\n\nCon questi pezzi, i nostri fratelli e le nostre sorelle hanno la speranza di vedere un altro giorno. Fai onore al capitano Bandarion.", 0x37a29ead, 0x86900340, 0x16f288f0, 0xe9eb73ab, 0x3637945c, "....." },
  [92422] = { "L'ira di Rath'mael", "Uccidi Rath'mael nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ per il guardiamorte Kristof, a Brill.", "Sono arrivati rapporti dal ⟦Lordamere Overlook=Belvedere di Lordamere⟧, nel cuore delle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧. Una nebbia empia ha invaso le strade e il cimitero, offrendo al Flagello lassù una certa copertura.\n\nI nostri esploratori dicono che a evocarli è un nuovo potere tra le loro file, un negromante di nome Rath'mael. Non possiamo permetterci di aspettare che passi, {name}.\n\nSe hai alleati, chiamali e porta il loro aiuto ai Reietti. Scaccia questa creatura dalle nostre terre.", nil, "Non ho dubbi che qualcuno della sua specie prenderà il suo posto, ma possiamo solo sperare che nel frattempo le loro file si assottiglino.\n\nGrazie, {name}.", 0x5b21ca69, 0x89893476, 0x68ec1579, nil, 0xa8e0a5f8, "...m." },
  [92432] = { "Una richiesta allarmante", "Fai rapporto all'immagine dell'arcimaga Modera, vicino alla città di Dalaran.", "Porto cattive notizie da Dalaran. Qualcosa ha sconvolto le nostre linee di potere, e i costrutti della città sono diventati instabili e distruttivi.\n\nNon sappiamo ancora cosa causi questo caos. L'alto consiglio ci ha ordinato di tenere la faccenda riservata, per non disonorare il nostro ordine. Ma non possiamo portare avanti questa farsa per sempre. Mentre parliamo, la città viene invasa!\n\nL'arcimaga Modera mi ha mandato a cercare aiuto all'esterno. Cerca la sua immagine vicino a Dalaran, accanto al ⟦Lordamere Lake=Lago Lordamere⟧.", nil, "Vedo che Jacques è riuscito a ottenere aiuto.\n\nAnche se non è strettamente permesso, non possiamo lasciare che il nostro orgoglio respinga gli alleati nel momento della disperazione. Non farti ingannare dalle guardie. Le cose sono tutt'altro che sotto controllo.", 0x551e242b, 0x959522b1, 0x14ceb11d, nil, 0x90d77a0d, "...m." },
  [92433] = { "Ora si cucina", "Porta $N1 Panino Saporito di Cervo a Hnaz Fiammacurva nella Selva Antica.", "Ehi! Sono piuttosto occupato a cercare di trasformare questi rimasugli in qualcosa di commestibile. Vuoi dare una mano? Mi servirebbe un po' più di varietà per questo pasto! Sarebbe bello avere qualcosa di diverso nel menu.\n\nC'è un goblin a ⟦Everlook=Lungavista⟧ che ha la ricetta dei Panini Saporiti di Cervo... perfetta per mani piccole come le mie. Se riuscissi a cucinarne un po', sarebbe fantastico! La carne di cervo la puoi ottenere dai cervi qui sulla montagna.", nil, nil, 0x16762640, 0xb540b4f0, 0x46912f53, nil, nil, "...mm" },
  [92434] = { "Sangue nelle strade", "Trova un modo per entrare a Dalaran lungo il ⟦Lordamere Lake=Lago Lordamere⟧.", "Qualunque cosa abbia fatto calare la barriera di Dalaran ha gettato la città nel caos. Ora che hai sistemato le loro pattuglie, non c'è momento migliore per entrare e scoprire i loro segreti.\n\nPrendi la chiave che hai trovato al campo d'internamento e cerca le fognature lungo il confine settentrionale della città. Con un po' di fortuna, quei maghi non avranno avuto motivo di proteggere con un incantesimo un punto d'accesso così... sgradevole.", "Fermo con quell'arma, {race}.\n\nPenso che scoprirai che quella chiave non basterà a superare le mie protezioni. Non penserai davvero che avremmo lasciato una simile vulnerabilità aperta in un momento come questo, vero?", "Non è certo una coincidenza che l'Orda si sia interessata alla mia città in un momento così precario.\n\nAnzi, ci contavo. Ho una proposta per te.", 0x417b19ab, 0xcc69013d, 0xcd6942fe, 0x00f10109, 0x0c17ab0a, "....." },
  [92446] = { "Un bel grattacapo", "Porta la carcassa di coniglio nel bosco a sud, attira allo scoperto Un bel grattacapo, sconfiggilo e riporta i suoi artigli a Zet'gan.", "A sud di qui, tra le foreste dove a volte vado a caccia, c'è un grande e astuto orso. Lo chiamiamo Un bel grattacapo, perché le sue zampe hanno beccato più di un abitante del villaggio ignaro. Tende imboscate ai cacciatori che tornano con la preda, colpendoli alla testa di sorpresa e stordendoli, poi ruba la cattura e corre di nuovo nella foresta.\n\nLui mi conosce bene, sa che gli do la caccia. Ma forse non conosce ancora il tuo odore.\n\nPrendi questa carcassa e attiralo fuori. Finiscilo e riportami i suoi artigli.", nil, nil, 0x51d2bda1, 0xdfd3f31b, 0x312bf5c5, nil, nil, "...mm" },
  [92449] = { "Addio al morbo", "Elimina $N1 Soldato Dimenticato e $N2 Famelico Scorticacarne.", "Da quando siamo scampati alla guerra, abbiamo faticato a garantire la nostra sicurezza, circondati da nemici da ogni parte, assediati da un pericolo costante.\n\nIl nostro vecchio rifugio a est è invaso dai non morti. Questi del Flagello vagano senza meta, un residuo triste ma pericoloso. Senza la guida dei loro comandanti sono perduti... ma ancora letali.\n\nPur avendoci provato, non siamo ancora riusciti a eliminare la loro presenza. Almeno, con il tuo aiuto, possiamo respingerli per garantire la nostra sicurezza... per ora.", nil, nil, 0x51840a50, 0xb93184f5, 0x7656d48e, nil, nil, "...mm" },
  [92454] = { "Benvenut<o/a>!", "Porta il ⟦Thendal Grove Gift Voucher=Buono Regalo del Boschetto di Thendal⟧ a Dalia Windbreeze.", "Benvenut<o/a> in World of Warcraft!\n\nPer ringraziarti in modo speciale di aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Dalia Windbreeze al ⟦Thendal Grove=Boschetto di Thendal⟧. Riceverai in dono un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza in World of Warcraft!", nil, nil, 0xd6adcb4f, 0x498e8e33, 0x3ed9c7cd, nil, nil, "...mm" },
  [92456] = { "Un campione verde", "Raccogli un ⟦Fel Infused Blossom=Bocciolo Infuso di Vil⟧ nella città di Dalaran per Shylamiir, a ⟦Stormwind City=Roccavento⟧.", "Se proprio devi infastidirmi, almeno renditi utile. Ho una commissione da farti sbrigare.\n\nPer essere una città di maghi, Dalaran ha un interesse sorprendente per la botanica. Il Kirin Tor se ne sta per conto suo, ma mi piacerebbe tanto avere un campione della loro vegetazione infusa di mana.\n\nÈ chiaro che ti trovi a tuo agio dove la gente non ti vuole: forse potresti trovare un modo per entrare in città. Se ci riesci, portami qualunque cosa cresca nel loro giardino centrale.", "Allora? Ce l'hai già?", "Questo... non è quello che avevo in mente.\n\nChiaramente la città sta passando più di quanto mi aspettassi. Ma ciò che hai trovato è altrettanto affascinante, se non di più.\n\nSuppongo che tu non sia così fastidios<o/a> come pensavo. Buon lavoro.", 0xb4915c29, 0xdc71b0cb, 0xb62ece69, 0x7f7213f3, 0xa92b1cf5, "....." },
  [92457] = { "Fame d'arcano", "Sconfiggi $N1 Seeking Remnant, $N2 Saturated Remnant e $N3 Mana Echo nella città di Dalaran per l'arcimaga Modera, fuori da Dalaran.", "La breccia ha colpito molti dei nostri servitori magici e degli incantamenti in tutta la città, compresi molti di quelli che provvedono alle nostre difese. Questa energia arcana frammentata ha richiamato elementali ribelli, che cercano di saturarsi di questa magia che scorre libera.\n\nMentre siamo impegnati con le protezioni e con altri incidenti gravi, faresti un favore al Kirin Tor se sfoltissi questa massa di elementali.", "Hai già ridotto il loro numero?", "Grazie {name}, questo progresso contribuirà a garantire la sicurezza di Dalaran.", 0x3d269d6e, 0xce5323ab, 0x7ce2d848, 0xa69d1a0a, 0x9a49476e, "....." },
  [92458] = { "Il cuore dello sconvolgimento", "Raccogli la ⟦Arcane Mote=Particella Arcana⟧ per l'immagine dell'arcimaga Modera, vicino alla città di Dalaran.", "Qualunque cosa abbia sconvolto le linee di potere, è partita dalla cima della Violet Citadel. Uno schianto fragoroso è risuonato dalle sale di sopra, e ora siamo invasi da un potere arcano incontrollato. Ci vogliono tutte le nostre forze solo per mantenere le protezioni.\n\nNon possiamo più permetterci di temporeggiare. Ci serve aiuto.\n\nIl Kirin Tor è occupato all'interno, ma per entrare ti servirà comunque una via meno in vista. Prendi questa chiave e raggiungimi nella cittadella quando sarai entrat<o/a> in città. Dobbiamo porre fine a questo sconvolgimento.", "A che serve il nostro orgoglio se non rimane in piedi una città di cui essere orgogliosi?", "Non so cosa hai visto lassù, {name}, ma non importa. Ciò che conta ora è contenere questa particella e porre fine a questa follia.\n\nHai fatto bene la tua parte. Ora il resto spetta a noi.", 0x0ac2f4b9, 0xf57ae5b1, 0x507642e9, 0x61e66bfb, 0x180cf406, "....." },
  [92459] = { "Amico del Kirin Tor", "Parla con l'arcimaga Celindra nella città di Dalaran.", "Al consiglio non piacerà sapere del nostro sotterfugio, ma non potrà negare i risultati. La città si sta calmando e possiamo abbassare le protezioni.\n\nMi sembra giusto che sia tu a portare la buona notizia. Porta questo granello arcano all'arcimaga Celindra, nella Violet Citadel.", "L'arcimago Modera parla molto bene di te. Cosa ti porta a Dalaran?", "Dove l'hai trovato? Nel salotto?\n\n<L'espressione dell'arcimago Celindra si oscura per un attimo prima di riacquistare la compostezza.>\n\nPenso sia meglio che tu cacci questo dai tuoi pensieri, <amico/amica>. Per ora il Kirin Tor accoglie un {class} competente come te. Benvenut<o/a> a Dalaran.", 0xa01b2371, 0x54834188, 0x3a8029bc, 0xf7d7e21e, 0xb9a39c81, "....." },
  [92460] = { "La maggiore età", "Parla con ⟦Rorian the Dayseeker=Rorian il Cercagiorno⟧ al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Guardati, con gli occhi che brillano, <pronto/pronta> all'avventura! Qui al ⟦Thendal Village=Villaggio di Thendal⟧ ci serve tutto l'aiuto possibile, e il tuo arrivo è più che benvenuto. Immagino che tu sia tutt<o/a> un fremito per ciò che ti aspetta. Dopotutto, si diventa adulti una volta sola nella vita.\n\nVa', cerca il capo del nostro villaggio, ⟦Rorian the Dayseeker=Rorian il Cercagiorno⟧, all'ingresso del grande albero padre, poco a ovest di qui. Sarà lui ad avviarti nel tuo viaggio.", nil, "Che i venti ti salutino, {name}. È un onore per me consegnarti oggi la reliquia della maggiore età, mentre vieni riconosciut<o/a> per il potenziale che porti agli shen'dorei. Il nostro popolo ha affrontato grandi avversità e persecuzioni nella sua complessa storia.\n\nOggi ricevi questa reliquia, una delle tante custodite da chi ti ha preceduto. Un giorno, quando le tue ceneri saranno sparse ai venti, passerà a un altro per continuare la nostra tradizione.\n\nPortando con te questa reliquia, sappi che i venti di casa saranno con te ovunque andrai.", 0x09074aad, 0x47c75d71, 0xd7d2d621, nil, 0x9ab09bea, "...m." },
  [92461] = { "Armonia ed equilibrio", "Uccidi 8 Vuldren Juvenile al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Per il nostro popolo viviamo tempi di grande incertezza. Affrontiamo sfide senza precedenti che potrebbero richiedere soluzioni audaci, ma qui al ⟦Thendal Grove=Boschetto di Thendal⟧ dobbiamo occuparci anche delle faccende ordinarie e banali. Prendi, per esempio, il recente e insostenibile aumento della popolazione di vuldren.\n\nI vuldren sono una parte vitale del nostro ecosistema. Tuttavia, gli squilibri vanno corretti per mantenere la delicata armonia che tutte le creature del ⟦Thendal Grove=Boschetto di Thendal⟧ condividono.\n\nVa' a est e sfoltisci un po' i vuldren laggiù.", "Per quanto sgradevole sia dover sopprimere creature viventi, questo tipo di mano guida è necessario per scongiurare il disastro nella nostra patria. È una lezione importante da imparare per uno come te.", "Grazie per il tuo servizio a Zephras, giovane {class}.\n\nDi solito i vuldren sono piuttosto docili, ma gli animali che vivono a Zephras sentono quando la magia nei venti è squilibrata, e questo può portare a comportamenti pericolosi e imprevedibili se nessuno interviene.", 0xe894e8ee, 0xa0a3f81d, 0xa21181a9, 0xdec7110e, 0x65e69857, "....." },
  [92462] = { "Indagine su un'infestazione", "Uccidi 8 Pesky Cirrusfly al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Uno dei nostri ranger ha segnalato di recente un'infestazione di cirrusfly qui al ⟦Thendal Grove=Boschetto di Thendal⟧.\n\nI cirrusfly possono essere pericolosi se si lascia crescere troppo lo sciame, quindi va' all'estremità orientale del bosco e sterminane più che puoi.", nil, "A giudicare dalla quantità di interiora d'insetto che hai addosso, dev'essere proprio una bella infestazione.", 0x79cd311b, 0xbb00ccfb, 0x08bf04cb, nil, 0x4468b320, "...m." },
  [92463] = { "La regina dei Cirrusfly", "Distruggi la Cirrusfly Queen al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Se la foresta è davvero così piena di questi insetti, uccidere le operaie non basterà.\n\nAddentrati nella foresta e trova la regina. Sarà vicino all'alveare, circondata da soldati più grossi e più aggressivi, quindi fa' attenzione.\n\nAbbattila e torna qui quando hai finito. Sarà un problema in meno a cui pensare da queste parti.", "Non bisogna sottovalutare i cirrusfly. Magari non sembrano pericolosi, ma devi stare attent<o/a> a quelli più grossi. Più sono grossi, più sono cattivi!", "Ottimo lavoro, {name}. Faresti carriera come ranger, se questa storia dell'«avventura» non dovesse andare.", 0x83a6ddbe, 0x682745f5, 0x7e74d152, 0x859bcc90, 0xc4ee2556, "....." },
  [92464] = { "Inquietudine elementale", "Parla con ⟦Yala Windwatcher=Yala Guardiavento⟧ al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Da quando i nostri benefattori elementali ci hanno lasciati, sembra che passiamo da un'inquietudine all'altra. Il problema che affrontiamo ora è che le manifestazioni dei venti vicino alle pietre erette a nord-est sono agitate.\n\nNon sono davvero coscienti di sé come gli spiriti senzienti del vento che un tempo vivevano qui: questi semplici spiritelli rispondono in egual modo alle forze, alle emozioni e alle intenzioni delle creature che li circondano.\n\nLa mia apprendista, ⟦Yala Windwatcher=Yala Guardiavento⟧, è andata a osservarli. Cercala e scopri cosa ha appreso.", nil, "Ti manda Rorian? Bene. Il tuo aiuto mi farebbe comodo.", 0x9b167222, 0x94de46d6, 0x7eb11290, nil, 0x6e32d6cc, "...m." },
  [92465] = { "Gli agitatori", "Uccidi $N2 Roiling Wind e $N1 Al'Aketh Convert al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Il culto degli Al'Aketh è una piaga per quest'isola. Sono senz'altro questi cultisti ad agitare i semplici spiritelli del vento che vivono qui e a renderli violenti.\n\nPurtroppo dovremo disperdere questi venti turbinanti prima che facciano del male a qualcuno. Dobbiamo anche mandare al culto un messaggio chiaro: nel bosco non sono i benvenuti.\n\nMi darai il tuo aiuto, {class}?", "È fatto?", "Mi addolora versare sangue shen'dorei qui nel bosco, ma facciamo ciò che dobbiamo.", 0xbed3e8bb, 0xcd6603dd, 0x1f47f35d, 0xcd001c89, 0x04fad858, "....." },
  [92466] = { "Il richiamo della terra", "Porta un ⟦Signet of Akir=Sigillo di Akir⟧ a Windshaper Boro.", "Anche se dobbiamo gran parte della nostra prosperità all'elemento del vento, il sentiero che percorriamo richiede di obbedire al richiamo di tutti e quattro gli elementi primari e di affrontare una prova per ciascuno. Prima di iniziare sul serio la tua prima prova, però, devi dimostrare la forza della tua determinazione.\n\nRecati ai menhir a est. Lì è stato avvistato un gruppo di convertiti degli Al'Aketh, e devono essere scacciati. Affronta quei cultisti e portami uno dei loro sigilli come prova delle tue gesta.", "Il culto degli Al'Aketh rappresenta il pericolo più diretto e urgente per la nostra patria. Le loro azioni sempre più estremiste hanno destabilizzato la nostra società e danneggiato il nostro legame, già indebolito, con gli spiriti dei quattro venti. Gli elementi esigono un'azione che dimostri la nostra tenacia e la nostra determinazione, qualità proprie del dominio dell'elemento della terra.", "Sei tornat<o/a> e hai portato ciò che ti ho chiesto, quindi la tua tenacia e la tua determinazione sono fuori discussione. Sei <pronto/pronta> per il prossimo passo, {name}.", 0xe316c17f, 0x56d019a1, 0x6a8b0ee0, 0x14db7dfc, 0xd306b4d5, "....." },
  [92467] = { "Il richiamo della terra", "Trova l'⟦Rise of Spirits=Ascesa degli Spiriti⟧ e bevi il ⟦Earth Sapta=Sapta di Terra⟧.", "Un sapta è una bevanda creata per legare i nostri spiriti agli elementi. Infusa di magia, la pozione permette a chi ha una volontà forte di vedere gli elementi come nessun altro può. Il tuo spirito sarà legato all'elemento per cui il sapta è stato creato, e solo pochi sciamani scelti ne conoscono la ricetta.\n\nIl sapta si beve sempre in un luogo sacro, e mai altrove: ricordalo.\n\nCerca l'⟦Rise of Spirits=Ascesa degli Spiriti⟧, su per il passo a est di qui. Bevi lì il tuo sapta e... be', vedrai ciò che devi vedere.", nil, "Ah... {name}... figli<o/a> dei quattro venti... Cerchi comprensione. Cerchi risposte. Perché i venti ti hanno abbandonat<o/a>? Come puoi riaverli? Sono risposte che non posso darti, perché non conosco i motivi né i movimenti dei venti.\n\nPosso però insegnarti molto della terra. La sua forza, la sua determinazione. Anche qui, in alto in questo mare infinito di nuvole, sei ancora una creatura della terra. Se speri di trovare la forza per parlare di nuovo con gli spiriti dei quattro venti, questo è il sentiero che devi percorrere.", 0xe316c17f, 0xf6800b6c, 0xc0ed3278, nil, 0xd7d8f099, "...m." },
  [92468] = { "Il richiamo della terra", "Porta il ⟦Rough Quartz=Quarzo Grezzo⟧ a Windshaper Boros al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Prendi da me questo ⟦Rough Quartz=Quarzo Grezzo⟧ e portalo a colui che chiamate Windshaper Boro come prova del nostro incontro. Creerà un totem per te, e questo frammento ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che la grandezza non conta, e che anche le cose più piccole possono durare più di molte altre.\n\nSii paziente, {name}. Resta forte. E cerca la saggezza. Questo è ciò che gli elementi ti chiedono. Alla fine diventerai una cosa sola con la terra: rispettala, come lei rispetterà te.", "Come imparerai, il sentiero che percorriamo non è semplice come può sembrare. Mentre cerchiamo di ritrovare la voce necessaria per parlare con gli spiriti dei venti, i venti sono solo una delle forze elementali di questo mondo. Solo comprendendo, e speriamo padroneggiando, tutti e quattro gli elementi ritroveremo la nostra voce per cantare di nuovo i canti del vento.", "Bene!\n\nIl totem che creerò per te è più di un simbolo del tuo rango tra gli {class}: ha capacità che vanno oltre. Uno degli usi del totem è come catalizzatore per gli incantesimi. Quegli incantesimi sono legati alla terra e, man mano che acquisirai sempre più saggezza, altre capacità della terra ti diventeranno accessibili.\n\nGli istruttori sapranno quando sarai <pronto/pronta> per una conoscenza superiore.\n\nMa per ora, prendi questo totem della terra...", 0xe316c17f, 0x5d706269, 0x79a2fea5, 0xeff959cf, 0x10d906ec, "....." },
  [92469] = { "Ritorno da Rorian", "Porta notizie degli Al'Aketh a ⟦Rorian the Dayseeker=Rorian il Cercagiorno⟧, al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Hai fatto abbastanza qui, {class}. Io resto a ripulire i ritardatari laggiù.\n\nTorna al villaggio e informa Rorian della presenza del culto. Non ne sarà contento.", nil, "È molto preoccupante, ma purtroppo non sorprendente. Seguiamo da tempo i movimenti del culto, ma ci siamo limitati a osservare da lontano. Agitare gli spiriti del vento vicino alle pietre erette è un chiaro passo avanti da parte loro.\n\nHai reso al ⟦Thendal Grove=Boschetto di Thendal⟧ un servizio difficile ma necessario, {name}. Grazie.", 0xd40ca8eb, 0x40558191, 0xc0e405c7, nil, 0x6e6e0bfa, "...m." },
  [92470] = { "Una matriarca immonda", "Uccidi 8 Ursera Scavenger e prendi la testa della madre della tana, Urs'anah, al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Rorian ti ha detto che ti tenevo d'occhio. Ora ti offro una prova di determinazione. Ma ti avverto: ti porterà in grave pericolo.\n\nVa' nelle grotte a ovest. Sfoltisci gli ursera laggiù e trova la loro matriarca, quella che i ranger chiamano «Urs'anah». Abbattila e portami la prova della sua morte. Fatto questo, avrai compiuto un passo importante sul tuo cammino.", "Ciò che ti chiedo non è facile, ma devi essere pront<o/a> a sfide ben più grandi, se vuoi sopravvivere abbastanza a lungo da servire l'isola di Zephras.", "Molto ben fatto. Hai abbattuto bestie e sconfitto intrusi del culto. Hai dimostrato grandi promesse, ma presto il tuo cammino dovrà portarti oltre la relativa sicurezza del ⟦Thendal Village=Villaggio di Thendal⟧.", 0x8559083b, 0x1984c594, 0x36d6dbf3, 0xd112c07a, 0xf35c3528, "....." },
  [92471] = { "⟦Aetheen of the Gales=Aetheen delle Burrasche⟧", "Parla con ⟦Aetheen of the Gales=Aetheen delle Burrasche⟧ al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Forse non te ne rendi conto, ma tutto ciò che hai fatto è stato una sorta di prova. Un assaggio di ciò che ti aspetta. Là fuori c'è un'isola grande, e Zephras ha bisogno di giovani avventurieri pieni di spirito come te, se vogliamo sopravvivere alle prove che il nostro popolo affronta.\n\nColei che chiamano ⟦Aetheen of the Gales=Aetheen delle Burrasche⟧ è una delle guide del nostro popolo qui sull'isola di Zephras, e ti ha tenuto d'occhio. Ha un compito che devi portare a termine. Parla con lei per saperne di più.", nil, "Rorian mi ha parlato molto di te. Probabilmente non mi conosci, ma sono un membro del Consiglio degli Anziani qui sull'isola di Zephras. Sono venuta a leggere il flusso dei venti qui al ⟦Thendal Grove=Boschetto di Thendal⟧. Sono qui anche per valutare i giovani shen'dorei come te che stanno diventando adulti.\n\nDunque dimmi, sei pront<o/a> a fare il prossimo passo? Sei pront<o/a> a servire l'isola di Zephras?", 0x09ec0d2f, 0xe70eafd5, 0x8e0f8a1b, nil, 0x0c68dc34, "...m." },
  [92472] = { "Il passo successivo", "Fai rapporto alla conestabile Aonda al ⟦Shen'dar Village=Villaggio di Shen'dar⟧.", "Una delle minacce più diffuse sull'isola di Zephras è il culto degli Al'Aketh. Sono fanatici religiosi votati al culto del presunto sovrano elementale di ⟦Skywall=Celaria⟧, Al'Akir il Signore del Vento. Sono brutali, ostinati, e il loro potere e le loro ambizioni diventano ogni giorno più letali.\n\nPresto il tuo cammino ti porterà al ⟦Shen'dar Village=Villaggio di Shen'dar⟧, a sud. Quando arrivi, presentati alla conestabile Aonda. Il culto minaccia Shen'dar, e lì hanno bisogno di aiuto. Di' ad Aonda che ti mando io.", nil, "Ti manda Aetheen, dunque? Lo ammetto, non mi sembri granché, ma il ⟦Shen'dar Village=Villaggio di Shen'dar⟧ non rifiuta un aiuto volenteroso, tanto meno un aiuto mandato dall'anziana Aetheen in persona.", 0x95c6443c, 0x8dffe20b, 0xb6601dd5, nil, 0x34e3eb4b, "...m." },
  [92473] = { "Un'invasione aggressiva", "Raccogli 6 Scrawny Ursera Claw dagli Scrawny Ursera del ⟦Thendal Grove=Boschetto di Thendal⟧.", "La tana degli ursera a sud-ovest sta diventando in fretta un problema. Proprio la settimana scorsa i ranger hanno dovuto uccidere un giovane ursera che si era avvicinato troppo al villaggio e aveva tentato di attaccare un bambino che giocava ai piedi dell'albero antico, al centro del villaggio.\n\nPer fortuna il bambino se l'è cavata. La fame e la disperazione rendono queste bestie troppo pericolose per lasciarle fare. Va' a sud e abbatti i più denutriti tra gli ursera. Quando hai finito, portami i loro artigli come prova.", "Ultimamente gli ursera sono diventati molto più aggressivi. Chissà cosa è cambiato per provocare questo comportamento.", "Ben fatto, {class}. I Rangers of the Grove sono in debito con te.", 0xa8134a87, 0xed3aad19, 0xabd8d5eb, 0x69f5dc9b, 0x39d32990, "....." },
  [92474] = { "Cadere con stile", "Salta dalla cima della torre di guardia del ⟦Thendal Grove=Boschetto di Thendal⟧ e usa la tua abilità Walk on Air per rallentare la caduta.", "Ma ciao, {name}! Vuoi fare un gioco?\n\nDevi solo salire su quella sporgenza... e poi saltare! Usa la tua capacità innata di camminare sull'aria per rallentare la caduta e vedi fin dove riesci a planare in avanti.\n\nLe regole sono inventate e i punti non contano, ma prendi punti bonus se riesci ad atterrare proprio davanti a ⟦Rorian the Dayseeker=Rorian il Cercagiorno⟧ e a fargli prendere uno spavento! Non gli piacerà, ma io mi farò di sicuro una bella risata se riesci a fargli perdere le staffe! Ah!", nil, "Quante volte devo dire a Myriaal di non incoraggiare gli altri a usare in modo sconsiderato i nostri doni di {race}!\n\nDetto questo, suppongo che un po' di pratica nella relativa sicurezza del villaggio sia... accettabile.\n\nIn futuro ti suggerirei semplicemente di usare la tua abilità con giudizio. Non vorrai esaurire la tua magia senza pensarci e poi non poterla usare quando ne avrai davvero bisogno.", 0x5a1c5b0a, 0x102a754b, 0xf3cf38d8, nil, 0xb57bbc92, "...m." },
  [92479] = { "Una lettera scarabocchiata", "Leggi la ⟦Scribbled Letter=Lettera Scarabocchiata⟧ e parla con Tordrin Stemblade nell'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di fartelo avere appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con il marchio di Tordrin Stemblade, il nostro istruttore dei cacciatori. Prenditi un momento per leggerla prima di occuparti di qualsiasi altra faccenda qui all'abbazia.", "Ah, hai avuto la mia lettera, {name}... bene.\n\nUna volta non avresti visto un {race} con un arco in mano neanche da morto... ora non più, pare. È un bene per ⟦Stormwind=Roccavento⟧, ma un male per i coboldi e le bestie mangiauomini della zona.", "Sistemati per bene, impara a conoscere il territorio e torna da me quando ti serve addestramento. Sarò qui notte e giorno.\n\nQuesta terra si fa più pericolosa, e incontrando altra gente scoprirai che tutti hanno problemi per cui farebbe comodo un aiuto... un aiuto che <un/una> {class} capace può dar loro. Buona fortuna.", 0x342ae89e, 0x0b04f03c, 0xaf9dc7c3, 0xb594010d, 0x84047297, "....." },
  [92480] = { nil, "Porta gli Orders from the High Priestess a Shen'Dar Village e consegnali a chi comanda lì.", "Il cultista che hai appena ucciso ha lasciato cadere quelli che sembrano ordini di una somma sacerdotessa del culto di Al'Akir. Si parla di una spia al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ e di operazioni del culto in un luogo chiamato ⟦Falaath Village=Villaggio di Falaath⟧. Le autorità del ⟦Shen'dar Village=Villaggio di Shen'dar⟧ vorranno saperlo.", nil, nil, 0xa0dc56ab, 0xc6d5f21e, 0x56bd77c7, nil, nil, "e..mm" },
  [92481] = { "Un allievo dell'arcano", "Esamina il ⟦Glowing Recall Crystal=Cristallo di Richiamo Luminoso⟧, poi parla con Dorii Brightwhisper al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Mentre eri via a occuparti del problema dei vuldren, Dorii Brightwhisper, che addestra i maghi del villaggio, ha lasciato per te questo cristallo della memoria. Contiene una specie di messaggio per te, quindi dagli un'occhiata. Poi troverai Dorii nell'edificio proprio dietro di me.", "Salute, {name}. È un privilegio per me portare avanti i tuoi studi di magia.", "Fatti guardare. Sì, credo che diventerai <un/una> giovane {class} di talento. Il potere dell'arcano si è affievolito tra la nostra gente, ma c'è chi vorrebbe riscoprire molto di ciò che abbiamo perso nei millenni trascorsi qui, tra le nuvole. Non ho dubbi che guiderai questa ricerca senza fine della conoscenza arcana e che alla fine ci renderai orgogliosi.\n\nParla di nuovo con me se vuoi compiere i tuoi prossimi passi.", 0xb3167a7d, 0x24eb4049, 0x40084095, 0x7a6bb7d5, 0xacf0d0f0, "....." },
  [92482] = { "La via del Cacciatore", "Leggi la ⟦Scribbled Note=Nota Scarabocchiata⟧ e poi parla con ⟦Tai'ree Farsight=Tai'ree Sguardo Lontano⟧ al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Mentre eri via a occuparti del problema dei vuldren, la nostra istruttrice dei cacciatori, ⟦Tai'ree Farsight=Tai'ree Sguardo Lontano⟧, ha lasciato per te questo biglietto. La trovi proprio laggiù, vicino al centro del villaggio. Leggi il biglietto e poi cercala.", "<Tai'ree ti fa un secco cenno del capo.>", "La strada che hai scelto, {class}, è irta di pericoli, e solo chi ha i sensi più acuti e i riflessi più pronti può prosperare nelle terre selvagge. Ti guardo e mi rivedo davanti al mio mentore, tanti anni fa. Credo che tu abbia ciò che serve, ma alla fine dipende solo da te.\n\nParla di nuovo con me se vuoi compiere i tuoi prossimi passi.", 0x66968684, 0x8ac97a8b, 0x21034971, 0x2c09ed68, 0x2aa1e90f, "....." },
  [92483] = { "A casa tra le ombre", "Leggi la ⟦Simple Note=Nota Semplice⟧, poi parla con Akeri Duskblade nella torre di guardia del ⟦Thendal Grove=Boschetto di Thendal⟧.", "Mentre eri via a occuparti del problema dei vuldren, il nostro istruttore dei ladri, Akeri Duskblade, ha chiesto di parlarti. Ha lasciato questo biglietto: leggilo prima, poi cercalo nella torre di guardia, qui al villaggio.\n\nÈ un tipo losco, ma d'altronde lo sei anche tu. Credo che andrete d'accordo.", nil, nil, 0xc76ec0d0, 0x9787d613, 0x78f1d36a, nil, nil, "...mm" },
  [92484] = { "Abbracciare gli elementi", "Esamina il ⟦Humming Recall Crystal=Cristallo di Richiamo Ronzante⟧, poi parla con Windshaper Boro al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Mentre eri via a occuparti del problema dei vuldren, Windshaper Boro, il nostro istruttore da Sciamano, ha lasciato per te questo cristallo della memoria. Esaminalo, per favore, poi parla con Boro proprio laggiù, vicino al centro del villaggio.", "Che i venti ti guidino, {name}.", "Lo senti? Il sussurro dei venti? Ne dubito, visto che gli spiriti hanno smesso di parlarci quando ci hanno lasciati, anni fa.\n\nQuelli di noi che vorrebbero di nuovo udienza presso gli spiriti dei quattro venti affinano la propria comprensione degli elementi e del mondo naturale, sperando ardentemente di ristabilire il dialogo interrotto così bruscamente.\n\nPercorrerai questa strada e padroneggerai gli elementi?\n\nParla di nuovo con me se vuoi compiere i tuoi prossimi passi, e ti addestrerò.", 0x935b0512, 0x59945334, 0x7abfcd0a, 0xabecb977, 0x6c6ded92, "....." },
  [92485] = { "Un allievo della natura", "Leggi la ⟦Folded Parchment=Cartapecora Piegata⟧, poi parla con Xyton Silverwind al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Mentre eri via a occuparti del problema dei vuldren, il nostro istruttore dei druidi, Xyton Silverwind, ha lasciato per te questo biglietto. Leggilo appena puoi, poi cerca Silverwind al piano terra di questo grande albero, proprio dietro di me.\n\nAscolta le sue parole e i suoi consigli: può insegnarti molto.", "Salute, sono Xyton Silverwind, custode del sapere druidico.", "La flora e la fauna dell'isola di Zephras formano un ricco arazzo di vita vibrante. L'ecosistema richiede un equilibrio costante per mantenere l'armonia della natura, e noi druidi siamo i custodi di quell'equilibrio. Vedo in te un grande potenziale, ma questa via non è facile, e avrai bisogno di una guida mentre crescerai in forza come <allievo/allieva> della zanna, dell'artiglio, della piuma e del ramo.\n\nParla di nuovo con me se vuoi compiere i tuoi prossimi passi.", 0x0911d9ff, 0xd2ab2b7f, 0xd328174b, 0x8a1a60b8, 0x03074af1, "....." },
  [92489] = { "Potere travolgente", "Uccidi il ⟦Mana Elemental=Elementale del Mana⟧ nella città di Dalaran per il gran occultista Andromath, a ⟦Stormwind City=Roccavento⟧.", "Il Kirin Tor è da tempo alleato dell'⟦Alliance=Alleanza⟧. Dopo la distruzione della loro città per mano dell'arcidemone Archimonde, l'un tempo fiera città dei maghi si è chiusa in sé stessa ed è diventata diffidente verso gli estranei.\n\nNegli ultimi anni hanno avviato la ricostruzione per riportare Dalaran all'antica gloria. Tuttavia, i rapporti indicano che faticano a contenere un'esplosione di energie arcane fuori controllo.\n\nDobbiamo aiutarli a disperdere questi attacchi, o rischiamo di perdere uno dei nostri alleati più potenti.", nil, "Una creatura di puro mana? Qualunque cosa stia causando questo disturbo è più potente di quanto suggerivano i rapporti iniziali.\n\nIl tuo aiuto ha guadagnato loro tempo prezioso e ha ricordato al Kirin Tor chi sono i suoi alleati. Buon lavoro, {name}.", 0x311e78b1, 0xa949729f, 0x0b3dd36e, nil, 0x44faa1cf, "...m." },
  [92500] = { "Un pezzo di cielo", "Trova il Gioiello dell'Orizzonte nei nidi delle arpie Alaverme sul ⟦Mount Hyjal=Monte Hyjal⟧ e portalo a Ketharas.", "Da quando il sacrario di Aviana è caduto in rovina, le arpie Alaverme si sono introdotte di nascosto e hanno rubato le ultime delle nostre reliquie druidiche. Una di queste, il Gioiello dell'Orizzonte, è una pietra blu scintillante benedetta dalla stessa dea piumata. Il tocco di Aviana potrebbe avere proprio il potere magico che ti serve per il tuo compito.\n\nGli Alaverme l'hanno senza dubbio nascosta dentro o vicino a uno dei loro nidi. Quando la trovi, portala a Ketharas.", nil, nil, 0x6cc57739, 0x96abbfea, 0xb5755db2, nil, nil, "...mm" },
  [92514] = { "Benvenuti al ⟦Shen'dar Village=Villaggio di Shen'dar⟧", "Parla con ⟦Illaya Amberwind=Illaya Vento d'Ambra⟧ e Coriella Calmbreeze al ⟦Shen'dar Village=Villaggio di Shen'dar⟧.", "Hai addosso quell'aria da \"Windshaper\". Me ne accorgo da quel pizzico di elettricità statica che sento sulla pelle quando mi trovo accanto a qualcuno toccato dagli spiriti. Prima di metterti davvero al lavoro qui, dovresti presentarti alla nostra anziana dei Windshaper, ⟦Illaya Amberwind=Illaya Vento d'Ambra⟧. È qui fuori, vicino al centro del villaggio.\n\nAh, e passa anche da Coriella Calmbreeze: gestisce la locanda del posto e può darti alloggio e provviste, se ne hai bisogno.", nil, "Sei già <passato/passata> da Illaya, allora? Ottimo. Di questi tempi c'è molta tensione tra l'High Order e i Windshaper, ma qui a Shen'dar mantengono i toni civili. Tutti qui sanno bene che abbiamo problemi più grossi dei loro battibecchi.\n\nOra che è fatta, mi sembri qualcuno che cerca qualcosa da fare con le proprie mani, e io ho un problema di banditi per cui speravo potessi aiutarmi.", 0x4c9d3c02, 0x5fceeb47, 0x1a5e7e29, nil, 0xc2e326dd, "...m." },
  [92515] = { "Il problema dei prideclaw", "Raccogli 10 Prideclaw Pelt dai Prideclaw negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", "Come se banditi e cultisti folli non bastassero, in questo periodo le colline brulicano anche di prideclaw. Cominciano a spingersi fino ai confini del villaggio e ogni giorno si fanno più audaci. È solo questione di tempo prima che si portino via l'animale o il figlio di qualcuno. Sarebbe un atto di pietà ridurne il numero adesso, piuttosto che dopo una tragedia.\n\nPortami una dozzina di pelli, più o meno. Posso ricavarne ogni genere di merce utile al villaggio.", "Se lo chiedi a me, i prideclaw sono piuttosto carini. Da una distanza di sicurezza... e stando dietro a qualcuno con una spada in mano, si capisce.", "Non ho mai detto che non sarebbe stato un lavoro sporco, no?", 0x60e9e4a1, 0x42c57bf7, 0xa20f234c, 0x84dcc399, 0x6bbd94a8, "....." },
  [92516] = { "Ippogrifi molesti", "Uccidi 8 Hippogryph Youth, 6 Hippogryph Protector e una Hippogryph Matriarch negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", "Uno stormo di ippogrifi ha da poco fatto il nido a sud-est del ⟦Shen'dar Village=Villaggio di Shen'dar⟧ e sta seminando il panico tra i viaggiatori sulla strada. Mi serve qualcuno che scenda laggiù e ce li sfoltisca un po'.", nil, "Ben fatto, e anche in fretta. Niente male davvero.", 0x51f3c6d8, 0x6f2bf4cf, 0xe1a423dd, nil, 0x93145b8a, "...m." },
  [92517] = { "L'elemento criminale", "Uccidi 10 Highlands Bandit e il loro capo, \"Badwind\" Bennic, negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", "Poco più a nord c'è una grotta, nascosta dietro una cascata. So bene che una banda di briganti opera da lì. Ci davano problemi già prima che arrivasse il culto, ma ora seminano il terrore. Purtroppo non posso permettermi di mandare gente a sgominarli.\n\nHo bisogno che tu vada lì e te ne occupi per me. Uccidine quanti più puoi e, se possibile, elimina il loro capo, quello che chiamano \"Badwind\" Bennic. Quella grotta è pericolosa, quindi fa' attenzione.", nil, "Con i banditi dispersi, abbiamo un problema in meno di cui occuparci. Anche se confesso che ora temo che i banditi sopravvissuti possano rivolgersi al culto in cerca di protezione, ingrossando ancora di più le sue fila, già allarmanti.\n\nComunque sia, ci prendiamo le vittorie dove capitano.", 0x40976c8d, 0xe1a7ec6c, 0x08ef374d, nil, 0x27e1dac8, "...m." },
  [92519] = { "Rifornimenti per l'infermeria", "Ritira una cassa di ⟦Packaged Tonics=Tonici Confezionati⟧ al laboratorio di Jorell, alla Fattoria di Go'shek, e torna dal dottor Gregory Victor a ⟦Hammerfall=Requie del Martello⟧.", "Lo speziale Jorell doveva portarci una cassa di antidoti ed elisir giorni fa, ma siamo ancora a mani vuote. Quello sciocco si sarà di nuovo avvelenato preparando intrugli in quella baracca senza aerazione che chiama laboratorio.\n\nSe vuoi aiutare ancora la nostra infermeria, saresti una persona molto più affidabile per questo incarico.\n\nSegui la strada fino alla Fattoria di Go'shek, a sud e un po' a ovest di qui. Probabilmente troverai la cassa già imballata e pronta, con Jorell sparito o del tutto incurante dei suoi obblighi.", nil, nil, 0x8adc3bb2, 0xd91cbe41, 0x8af3012a, nil, nil, "...mm" },
  [92521] = { "La torre del demone", "Spia il folletto di Hnaz alla torre con il satiro prigioniero.", "Lo sai che sono uno stregone, vero? Ora mi tocca vivere nello squallore e tagliare carne, ma un tempo ero un potente mago!\n\nIl mio folletto continua ad allontanarsi e, anche se potrei semplicemente richiamarlo, sono un po' curioso di sapere cosa combina. Sgattaiola via per parlare con un satiro incatenato in una torre a sud-est di qui. Se non ti dispiace, vorrei sapere di cosa parlano.\n\nSono sicuro che non c'è nulla di cui preoccuparsi, ma con i demoni non si sa mai, giusto?", nil, nil, 0xfa11a2a6, 0xa0d7493d, 0x69f8e08a, nil, nil, "...mm" },
  [92528] = { "Tra i fedeli", "Guardati intorno al ⟦Falaath Village=Villaggio di Falaath⟧ per scoprire le intenzioni del culto negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", "I fedeli di Al'Akir si rafforzano a ogni nuova recluta entusiasta come te. Come vedi, la nostra forza dà forma alla tempesta stessa!\n\nDi solito ti manderei subito dallo Skypriest Aanders per la valutazione, ma al momento è impegnato a ricevere un ospite alla locanda sul lato nord del villaggio. Ti prego, per ora evita quel posto. Una recluta non rasata come te al cospetto di un simile ospite sarebbe sconveniente.\n\nPer ora, cerca solo di non intralciare nessuno.", nil, "C'era Lorthuna in persona? È a capo di tutto quel maledetto culto!\n\nSe stanno muovendo contro il ⟦Shen'dar Village=Villaggio di Shen'dar⟧ e la torre di guardia occidentale, dobbiamo essere pronti. La cosa strana è... perché la torre di guardia?\n\nIl villaggio lo capisco, ma la torre? Non ha grande importanza strategica, se non come piccolo posto di vedetta.\n\nIn ogni caso, saremo pronti ad accoglierli. Scopriranno che la gente degli altopiani non si lascia cogliere alla sprovvista così facilmente come credono.", 0x204012e1, 0x8419ec91, 0xaaed2c17, nil, 0x64c8a1fa, "...m." },
  [92529] = { "⟦Falaath Village=Villaggio di Falaath⟧", "Presentati al missionario Jasaan vicino all'ingresso del ⟦Falaath Village=Villaggio di Falaath⟧.\n\nSe perdi il tuo Mark of Akir, parla con ⟦Sania Silverstream=Sania Vena d'Argento⟧ al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per riottenerne l'effetto.", "Mi rallegra il cuore che tu voglia servire Al'Akir. Le prove che il nostro popolo affronta oggi nascono dal nostro stesso compiacimento. Siamo diventati superbi e abbiamo dato per scontata la generosità dei venti. La stagnazione che ne è seguita è il motivo per cui gli spiriti del vento ci hanno abbandonati.\n\nSolo con atti di contrizione potremo sentire di nuovo la carezza del vento. Se cerchi la compagnia di altri shen'dorei che la pensano come te, va' al ⟦Falaath Village=Villaggio di Falaath⟧ e cerca lì il missionario Jasaan. Ti marchierò, così che i fedeli ti riconoscano come recluta.", nil, "Che cos'è questo? <Un/Una> <nuovo/nuova> <accolito/accolita> che desidera servire il Signore del Vento, mandato da sorella Sania? Oggi siamo davvero benedetti dal tocco dei quattro venti!\n\nAccogliamo tutti coloro che desiderano crogiolarsi nelle benedizioni di Al'Akir.", 0x20d8f218, 0x4a06c83e, 0x47085e11, nil, 0xa831957e, "...m." },
  [92532] = { "La via del guerriero", "Leggi la ⟦Crumpled Note=Nota Sgualcita⟧ che ti è stata data, poi cerca la maestra di spade Ren nella torre di guardia del ⟦Thendal Village=Villaggio di Thendal⟧.", "Mentre eri via, la nostra istruttrice dei guerrieri, la maestra di spade Ren, ha chiesto che ti mandassimo da lei al tuo ritorno. Ha lasciato anche questo biglietto per te.\n\nLeggilo, poi cerca la maestra di spade Ren nella torre di guardia del villaggio.", "Quindi sei qui per l'addestramento?", "Stai per intraprendere un viaggio pericoloso. Il nostro mondo sta cambiando e, se il nostro popolo spera di sopravvivere, avrà bisogno di chi ha la volontà di guidare e proteggere gli altri. Man mano che crescerai in potere avrai bisogno di una guida. Vieni da me: farò il possibile per addestrarti mentre progredisci.\n\nBuona fortuna, {name}, che i venti ti guidino.", 0x72377474, 0x2103fb1b, 0x3cff1264, 0x8a44f6ef, 0x95a3eb62, "....." },
  [92533] = { "Attrezzi contorti", "Recupera un Kris del Ritualista Malvagio e un Bastone di Scorzanodosa Rinculante dai cultisti di Spinanera.", "Ho lavorato il ferro per tutta la vita e sento quando un'arma si è distorta dal suo scopo. Il culto degli Spinanera forgia attrezzi pensati per ferire la terra tanto quanto la carne. Uccidi i loro cultisti e portami ciò che hanno con sé: uno dei loro bastoni e un pugnale rituale.\n\nNon si limitano a uccidere con le loro lame, le stanno avvelenando di proposito.\n\nStudiando i segni lasciati dalla loro corruzione, possiamo capire come si diffonde la loro influenza. Forse impareremo a fermarla o persino a invertirla.", nil, nil, 0xf1f3bd8a, 0xb75a3fa9, 0xcce7df97, nil, nil, "...mm" },
  [92534] = { nil, nil, nil, nil, nil, 0x0b64e98b, nil, nil, nil, nil, "emmmm" },
  [92544] = { "Teppisti degli Al'Aketh", "Uccidi 6 Al'Aketh Brute, 4 Al'Aketh Neophyte e Malduko Cloudcrush al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Una banda di teppisti del culto degli Al'Aketh si è stabilita vicino alle rovine del tempio, appena a sud-ovest di qui, guidata da un vero mostro di nome Malduko Cloudcrush. Questa marmaglia è stata senza dubbio mandata qui dalla somma sacerdotessa Lorthuna, dal ⟦Shrine of Akir=Sacrario di Akir⟧, per attaccare i viaggiatori e costringere la nostra gente a unirsi al culto.\n\nDevo restare qui al mio posto per avvertire del pericolo i viaggiatori che lasciano il bosco, ma ti sarei riconoscente se potessi occuparti di quei cultisti e del loro capo per me.", nil, "Ho dovuto fare di tutto per trattenermi dal lasciare la mia posizione e unirmi a te. Posso solo sperare che questi zoticoni abbiano capito l'antifona e se ne vadano presto da qui.\n\nGrazie, {class}. Hai la gratitudine dei Ranger del ⟦Thendal Grove=Boschetto di Thendal⟧.", 0x0dea7326, 0xf2db9fef, 0x02f45348, nil, 0x0dce1895, "...m." },
  [92550] = { "Scompiglio sugli altopiani", "Raggiungi le rovine del ⟦Falaath Village=Villaggio di Falaath⟧ e uccidi 6 Al'Aketh Stormcaller e 4 Living Lightning, poi prendi la testa di Commander Cyclas.", "La nostra difesa migliore potrebbe essere proprio un attacco deciso. Il vantaggio che abbiamo ora è che sappiamo che un attacco sta arrivando. Quello che non si aspettano è che colpiamo noi per primi.\n\nTi ho già chiesto molto, ma ti prego, torna al ⟦Falaath Village=Villaggio di Falaath⟧. Uccidi quanti più cultisti puoi e, se riesci ad avvicinarti abbastanza, uccidi il comandante e portami la sua testa. Io resterò qui a organizzare i cittadini e i nostri pochi Pacificatori per preparare la difesa... nel caso tu non tornassi.", "È bello ribaltare la situazione con questi fanatici.", "Siano ringraziati i venti, sei <tornato/tornata>!\n\n⟦Sania Silverstream=Sania Vena d'Argento⟧ è sgattaiolata fuori dal villaggio poco prima del tuo ritorno, senza dubbio in fuga alla vista della nostra gente che si armava.\n\nHai fatto una cosa straordinaria per la gente del ⟦Shen'dar Village=Villaggio di Shen'dar⟧ e ti siamo debitori. Se il culto tornerà sugli altopiani, scoprirà che Shen'dar non è un bersaglio così facile.\n\nChe i venti ti guidino, {name}.", 0xac4c0e34, 0x9fc6a9c3, 0x20b41f51, 0x1a5c2079, 0x89e963fe, "....." },
  [92551] = { "Provviste rubate", "Raccogli 10 pacchi di ⟦Stolen Shen'dar Supplies=Rifornimenti Shen'dar Rubati⟧ al ⟦Falaath Village=Villaggio di Falaath⟧, negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", "Ho sentito dire che forse andrai al ⟦Falaath Village=Villaggio di Falaath⟧? Già che ci sei, tieni d'occhio i nostri depositi di provviste rubati.\n\nDa mesi gli Al'Aketh assaltano le carovane che portano le nostre merci, come cibo e pietre del vento, da e verso le pianure. Ovviamente danno la colpa ai banditi, ma sappiamo tutti che la roba finisce nello stesso posto. Se a Falaath è rimasto qualcosa, sarebbe un grande aiuto se riuscissi a recuperarlo.", "Qui c'è tanta gente della tua razza, {race}, affamata e disperata, che ha bisogno di queste provviste.", "Fantastico! Senza le nostre consegne regolari di provviste tiravamo a malapena avanti. Lavorerò con il conestabile perché queste provviste vengano ridistribuite agli abitanti che ne hanno più disperato bisogno.", 0x97ab9949, 0x20dd891c, 0x781e5b88, 0x24447cc0, 0x6a50e0dd, "....." },
  [92553] = { "Dispense da riempire", "Raccogli $N1 Piccolo Uovo e $N2 ⟦Strider Meat=Carne di Zampalunga⟧ dalle creature degli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", "Hai voglia di lavorare un po'? Mi farebbero comodo i muscoli di un tipo forte e avventuroso come te. Con l'aria pericolosa che tira da queste parti, ultimamente nessuno ha avuto tempo di cacciare o raccogliere cibo, e mi serve qualcuno che vada là fuori a procurarmi uova fresche e Carne di Zampalunga per sfamare il villaggio.\n\nSarei felice di insegnarti una delle mie famose ricette, se mi porti ciò che mi serve. Che ne dici?", "Per quanto le cose cambino qui su Zephras e per quanto diventino incerte, dico sempre che una pipa piena di peacebloom essiccato e una bella pancia piena sono un conforto impareggiabile!", "Queste uova non sono facili da trovare ma, che il vento mi salvi, sono DELIZIOSE fritte in un po' di sego di ursera.\n\nSe hai un po' di tempo libero e ti piace cucinare, posso insegnarti qualche trucco e segreto che ho imparato. Basta una parola e sarò felice di addestrarti.", 0x5295b2aa, 0xd69fc243, 0xf0409ea7, 0x0ebed89e, 0x4e67a6e0, "....." },
  [92579] = { "Verso Valanaar", "Consegna Aonda's Written Report a Valennia Stormfist a Valanaar.", "Per ora sembra che il pilone e il villaggio siano al sicuro, quindi vorrei che portassi questo rapporto a Valennia Stormfist a Valanaar, sul margine sud-orientale dell'isola. Valennia è a capo dei Pacificatori dell'isola e deve sapere cos'è successo qui.\n\nIl culto si sta espandendo in fretta e finora i Pacificatori hanno evitato lo scontro diretto, ma quei tempi sono finiti. Valanaar dovrà essere pronta a combattere.\n\nIn ogni caso, grazie. A Shen'dar avrai sempre degli amici, {name}.", "Una lettera di Aonda. Che cosa avrà combinato quella volpe degli altopiani?", "<L'espressione di Valennia si incupisce mentre legge la lettera.>\n\nAonda ti ha affidato questa lettera e in essa parla abbastanza bene di te, quindi cercherò di fidarmi anch'io. Prima di parlare ancora, devo consultarmi con i pochi Pacificatori che ci restano qui e preparare un piano nel caso il culto colpisca qui la prossima volta. Per ora goditi il soggiorno a Valanaar.\n\nSe cerchi qualcosa da fare, ci sono molti abitanti che probabilmente avrebbero bisogno dell'aiuto di <un/una> giovane <avventuriero/avventuriera> forte come te.", 0x74fef55e, 0x117fb641, 0x1bb0140d, 0xc4bd4279, 0x4cbd429f, "....." },
  [92591] = { "Morte definitiva", "Usa la Torcia del Sopravvissuto sulla Pila d'Ossa, poi raccogli l'Amuleto del Rianimatore.", "Abbiamo provato a lasciare la montagna, ma i nostri tentativi sono sempre stati vanificati dal Flagello. Un potente lich rianima i resti di quelli che distruggiamo e ce li rimanda contro. Finché quel lich resisterà, non saremo mai al sicuro.\n\nIl lich ha un mucchio di ossa da cui ricostruisce gli scheletri. Prendi questa torcia e dai fuoco al mucchio di ossa tra le rovine. Il lich non mancherà di reagire.\n\nPortami il suo amuleto, così potremo distruggerlo e liberarci del lich una volta per tutte.", nil, nil, 0x24295886, 0x7700a96d, 0x92824a4c, nil, nil, "...mm" },
  [92592] = { "Morte definitiva", "Usa la Torcia del Sopravvissuto sulla Pila d'Ossa, poi raccogli l'Amuleto del Rianimatore.", "Abbiamo provato a lasciare la montagna, ma il Flagello ci ferma sempre. Un potente lich rianima i resti di quelli che distruggiamo e ce li rimanda contro. Quel lich è il motivo per cui non possiamo vincere!\n\nIl lich ha un mucchio di ossa che usa per ricostruire gli scheletri. Prendi questa torcia, va' alle rovine e brucia il mucchio di ossa. Il lich di sicuro reagirà.\n\nPortami il suo amuleto e lo distruggiamo e ce ne liberiamo per sempre!", nil, nil, 0x24295886, 0x7700a96d, 0x143d52c5, nil, nil, "...mm" },
  [92593] = { "Valanga di corruzione", "Entra a Dae'gun e individua un punto d'osservazione elevato, poi riferisci i dettagli a Johun.", "Be', hai dimostrato di essere abbastanza capace da occuparti dei lavoretti. Ora vediamo se ci si può fidare di te per minacce più grandi.\n\nAllestire una stazione di intelligence qui è solo il primo passo del lavoro. Se vuoi contribuire a gettare le fondamenta di ciò che verrà, entra con cautela a Dae'gun, i resti della base dell'⟦Horde=Orda⟧.\n\nTrova un punto elevato adatto a un posto di osservazione. Torna a riferire con i dettagli sulla zona e vedremo di farti dare un briefing come si deve.", nil, nil, 0x9875abf7, 0xbfdab3a8, 0x3cdf9751, nil, nil, "...mm" },
  [92594] = { "Legna da ardere, più o meno", "Distruggi $N1 Arbusto Contaminato per Kaylaena Sussurrafonte all'officina nelle Colline Corrotte.", "Mentre giri per la montagna, non posso resistere dal chiederti un altro piccolo favore...\n\nHai visto tutti quei cespugli e quelle piante vili che ricoprono le colline laggiù? Si scopre che bruciano piuttosto bene, il che è sia un bene sia un male. Pratici da buttare in una piccola fornace, ma anche un rischio quando si aggrovigliano e bloccano ingranaggi... o stringhe degli stivali!\n\nDiradane il numero mentre scendi e raccoglierò le erbacce di persona una volta seccate.", nil, nil, 0xae2126ae, 0xd4a28229, 0xbefbf7e8, nil, nil, "...mm" },
  [92595] = { "I Windshaper", "Ascolta ciò che ⟦Illaya Amberwind=Illaya Vento d'Ambra⟧ ha da dirti.", "<Illaya ti sorride con calore.>\n\nSono lieta che tu sia <tornato/tornata> a parlare con me, <figlio/figlia> dei venti. L'ho saputo fin dal primo istante in cui sei <giunto/giunta> al mio cospetto: lo skysight è forte in te. Ti sorprende? Anche chi non si è addestrato come Sciamano può possedere il dono.\n\nVieni, parliamo del mandato dei Windshaper, della natura delle nostre lotte su Zephras e delle sventure del nostro popolo.", "Il mondo sta cambiando e il cammino davanti a noi sarà difficile. Abbiamo una sola possibilità di salvarci.", "Credo che ora tu capisca quanto sia importante la missione dei Windshaper. Ogni anima che padroneggia lo skysight è di vitale importanza, se speriamo di ristabilire il dialogo con gli spiriti dei venti.\n\nTra le minacce interne, come gli Al'Aketh, e l'incertezza sulla nostra sicurezza qui a ⟦Skywall=Celaria⟧, è nostra responsabilità come Windshaper usare i nostri doni per salvare la nostra casa e far sì che gli shen'dorei sopravvivano a questi tempi difficili.", 0x780f72d7, 0xc822e25f, 0x377f999c, 0x7dec2ce6, 0x60d678be, "....." },
  [92596] = { "L'High Order", "Siediti e parla con Rathiril Sunlance.", "L'aura di energia arcana che ti circonda è forte, anche se non hai ricevuto l'iniziazione da mago. Sono certo che avrai grandi capacità come <avventuriero/avventuriera>, e il tuo legame con la nostra antica magia sarà sempre un vantaggio per te, anche se non dovessi mai pronunciare una sola parola di potere per lanciare un incantesimo.\n\nVieni, sediamoci e parliamo un po' del mio ordine, della natura dell'arcano qui su Zephras e delle sventure del nostro popolo.", "La nostra terra sta attraversando dei cambiamenti, ma potrebbe ancora venirne qualcosa di buono.", "La missione dell'High Order è vitale per la sopravvivenza del nostro popolo. Teniamo i nostri benefattori elementali nella massima considerazione, ma dobbiamo affrontare la realtà: se ne sono andati, e siamo soli.\n\nTra le minacce interne, come gli Al'Aketh, e le incertezze sulla nostra sicurezza su questo piano, è nostro destino, come discendenti degli ⟦Highborne=Alti Nobili⟧ della nostra patria ancestrale di Eldre'Thalas, usare i nostri doni perché gli shen'dorei possano di nuovo reggersi sulle proprie gambe.", 0x022195d4, 0x8d1edbd7, 0xfb71220a, 0xe20f6ce0, 0xf653c22f, "....." },
  [92597] = { "Leggere le linee di potere", "Usa la tua abilità razziale Read Leyline sulla linea di potere al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Qui nel piano elementale traiamo gran parte della nostra forza arcana dalle linee di potere che scorrono ancora nel terreno sotto i nostri piedi. Di recente queste linee hanno cominciato ad affiorare in superficie, dandoci un accesso più diretto e potente a queste energie arcane latenti.\n\nVa' ai monoliti a nord-est. Lì c'è una linea di potere. Attingi al tuo diritto di nascita e assorbine l'energia.", "Realizzare il nostro vero potenziale come figli e figlie degli Alti Nobili è la nostra unica via di salvezza. I Windshaper non sono molto meglio degli Al'Aketh: si prostrano davanti a creature ultraterrene e indifferenti.", "Lo senti? Sì? Bene! Hai mosso i primi passi. Scoprirai che, con le tue capacità, potrai attingere all'energia magica latente in molti luoghi. Farlo ti darà una miriade di benefici, alcuni profondi, altri più sottili. Non lo saprai finché non vi attingerai, ma è questo il bello del dono... rendere noto l'ignoto.\n\nSe vogliamo sopravvivere a questi tempi terribili, dobbiamo essere incrollabili nella ricerca della conoscenza... e del potere.", 0x29bc8646, 0xc396807e, 0x2c9839e6, 0x1c118522, 0xba617b0f, "....." },
  [92598] = { "Il dono dello skysight", "Usa la tua abilità razziale Skysight presso l'Elemental Convergence al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Come Windshaper, hai la capacità di usare il sacro skysight che gli spiriti elementali ci hanno donato. Raggiungi i monoliti a nord-est del villaggio. Trova lì la convergenza elementale e usa il tuo dono.\n\nScoprirai che puoi attingere allo skysight ovunque, ma il suo beneficio è molto più potente se lo fai in presenza di una convergenza elementale. A volte potresti anche ricevere altre perle di saggezza dagli spiriti attirati da simili luoghi di potere.", nil, "Come un muscolo, il tuo skysight va esercitato se speri di diventare più forte nel dono. Usare lo skysight per colmare la distanza tra il mortale e lo spirituale potrebbe rivelarsi prezioso nelle tue avventure.\n\nFaresti bene a ricordare ciò che hai imparato oggi. La nostra capacità di usare i nostri doni per ascoltare ciò che ci dicono gli elementi potrebbe essere la chiave della nostra sopravvivenza.", 0x72459b2b, 0x16d8780d, 0x316bc5c0, nil, 0x0d8764c0, "...m." },
  [92609] = { "Piume in volo", "Raccogli $N1 Piuma di Gufo di Hyjal per Zet'gan.", "Abbiamo provato ad andarcene molte volte, ma continuiamo a essere trascinati indietro a difendere i nostri fratelli e sorelle. Con le difese che si assottigliano, è ora di fare rifornimento.\n\nOggi ci servono frecce. Tante, tantissime.\n\nTrova quei grandi, bellissimi uccelli e portaci le loro lunghe piume per le frecce che vanno dritte.", nil, nil, 0x4fa7c2f1, 0x2f998da8, 0x9c7889e6, nil, nil, "...mm" },
  [92612] = { "Aiuto da ⟦Moonglade=Radaluna⟧", "Recati a ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧, e chiedi aiuto a ⟦Dendrite Starblaze=Dendrite Ardistella⟧ a nome di Ketharas.", "<Ketharas prende il ramo e lo studia. Inizia a sussurrare un incantesimo druidico e il ramo comincia a brillare più intensamente. Anche il cristallo verde malaticcio comincia a reagire, come se attirasse la luce che lo circonda.>\n\nI segreti di questo ramo sono purtroppo al di là della mia capacità di discernimento. Ma percepisco... qualcosa.\n\nPrendi il ramo e va' alla città di ⟦Nighthaven=Nottequieta⟧ a ⟦Moonglade=Radaluna⟧. Chiedi aiuto a ⟦Dendrite Starblaze=Dendrite Ardistella⟧.", nil, nil, 0xf8b6a75b, 0x425de0f3, 0xc1d3e054, nil, nil, "...mm" },
  [92640] = { "Tempi disperati", "Parla con Valennia Stormfist a Valanaar e segui le sue istruzioni.", "Dato che affrontare il culto in campo aperto non è possibile, la nostra migliore occasione sarà sfruttare questo momento per attaccare il santuario stesso. Possiamo togliere di mezzo Lorthuna prima che porti a termine la sua parte del piano.\n\nGuarda caso, Valennia prepara da tempo una strategia per un possibile assalto al santuario. L'unico problema è che ci servirà aiuto.\n\nParla con Valennia per i dettagli.", nil, "In questo momento la tensione tra i Windshaper e l'High Order è alta, ma non potremmo sperare di attuare questo piano senza entrambi i gruppi dalla nostra parte.", 0xbee67de8, 0xe0ffb7d6, 0x807c5f5e, nil, 0x4f07dec6, "...m." },
  [92642] = { "Colpire i rifornimenti", "Uccidi 4 Al'Aketh Healer e 8 Al'Aketh Brawler nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Valennia ha mandato una sola persona ad aiutarci a respingere un assalto in piena regola... per i venti.\n\nNon sembri granché, ma prendo quel che passa il convento. Dobbiamo infliggere più danni possibile per fermare tutto questo presto. La mia gente non può resistere ancora a lungo.\n\nScendi dalla collina e colpisci i loro rifornimenti. I loro guaritori mandano avanti gli assalitori senza sosta: se li eliminiamo, forse riusciremo a raccogliere le forze e a respingerli. Anche ogni altro cultista che uccidi là fuori ci è d'aiuto.", nil, "Sei ancora <vivo/viva>? Ringraziamo i venti per i piccoli miracoli, immagino.", 0x4ee49cde, 0xfd87bd08, 0x9d51a92f, nil, 0x891c6ecb, "...m." },
  [92643] = { "Il voltagabbana", "Trova il cultista voltagabbana nella casa appena dentro gli altopiani, a nord-ovest di Valanaar.", "Tra gli Al'Aketh c'è un voltagabbana. Dice di conoscere le vere intenzioni del culto per l'isola e vuole consegnarsi, ma lo farà solo con garanzie di protezione.\n\nQuesto disertore si nasconde in una dimora isolata appena a nord-ovest di Valanaar, dentro gli altopiani. Mi serve qualcuno che possa andarci con discrezione, trovare il traditore e scortarlo da noi. Potrebbe essere una trappola, ma se queste informazioni sono importanti quanto sostiene il traditore, vale la pena correre qualche rischio.", nil, "<Quest'uomo è chiaramente morto, ucciso dagli assassini che hai combattuto fuori dalla casa. Mentre ti inginocchi per esaminare il corpo, noti il riflesso scintillante di qualcosa di lucido...>", 0x19e86215, 0xbb45643c, 0x0734bd6e, nil, 0xfe7530c0, "...m." },
  [92644] = { "Brutte notizie", "Consegna il cristallo luminoso a Talanaanis Shadowsong a Valanaar.", "<Frughi sotto il corpo ancora caldo del cultista voltagabbana e recuperi un piccolo cristallo azzurro luminoso. Sembra danneggiato, ma potrebbe comunque essere importante. Potrebbe interessare all'alto anziano Shadowsong.>", "Sei <tornato/tornata>? E... <solo/sola>?", "Il voltagabbana era già morto quando sei <arrivato/arrivata>, dici? È una brutta notizia.\n\n<Consegni il cristallo che hai trovato sul corpo del cultista morto.>\n\nInteressante...", 0xfee67657, 0xd4f77d59, 0x29c73863, 0x9c8dd0dd, 0xf4127133, "....." },
  [92645] = { "Abbattere \"the Breaker\"", "Uccidi Commander Belguilos nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Sarà dura respingere questo attacco, a meno che non riusciamo a eliminare la comandante del culto. La chiamano Belguilos \"the Breaker\", ed è un vero terrore. Era una pacificatrice prima che il culto sfuggisse di mano, e già allora era... strana. Da cultista posso solo immaginare quanto possa essere peggiorata.\n\nForse ti sto mandando a morire, ma qualcuno deve eliminare Belguilos se vogliamo sopravvivere. La troverai alla villa ai piedi della collina. Buona fortuna, {class}.", nil, "Belguilos è morta? Che i quattro venti ti benedicano, {class}.\n\nForse, dopotutto, ne usciremo vivi.", 0xe9120191, 0x51edce72, 0x069c8615, nil, 0x3891e497, "...m." },
  [92646] = { "Affrontare Lorthuna", "Prendi il portale verso le ⟦Rohashi Spires=Guglie Rohashi⟧, qui sopra, e unisciti a Elaadrin Evengale e Ayessa Dawnsinger nello scontro con la somma sacerdotessa Lorthuna.", "Lorthuna è fuggita sulle guglie qui sopra attraverso una specie di portale. Ayessa ed Elaadrin le sono andati dietro. È successo solo pochi istanti fa.\n\nTemo di aver preso un colpo di troppo: per me il viaggio finisce qui. Attraversa il portale, trova Ayessa e aiutali a fermare Lorthuna.\n\nA meno che non arrivino presto i rinforzi che Elaadrin e Ayessa dicono di aver chiesto, da qui in poi dovrai cavartela da te. Buona fortuna, {class}.", nil, "Ho mandato alcuni dei nostri guaritori ad assicurarsi che Valennia e le sue forze rimaste tornassero sane e salve. Ora dovrebbe riposare nella dimora dell'alto anziano.\n\nMuln è già ripartito per Azeroth, ma lui e io abbiamo parlato di ciò che attende i Windshaper e della nostra missione su Azeroth. Purtroppo ora l'isola è più vulnerabile che mai e ci serve un piano per proteggere Zephras da ciò che verrà.", 0x90290d9d, 0x05b5bc13, 0xc9ea1d15, nil, 0xd1f90ba8, "...m." },
  [92679] = { "Tributo di sangue", "Ascolta ciò che Alvarion Windfield ha da dirti e trova Aamelia Windfield al ⟦Windfield Orchard=Frutteto di Campovento⟧.", "S... salve, <straniero/straniera>. Hai l'aspetto di chi sa il fatto suo come <avventuriero/avventuriera>. Io...\n\n<L'uomo Skyborne fa una smorfia, chiaramente in preda a un dolore terribile.>\n\n...mi chiedevo se cercassi lavoro. Sono venuto qui a Valanaar a reclutare combattenti che mi aiutino a salvare la mia fattoria. Se ti interessa, ti prego, va' a cercare mia moglie Aamelia Windfield nel nostro frutteto, a ovest di Valanaar, nelle pianure.", "Cosa? Alvarion è vivo?", "<Aamelia ascolta mentre le spieghi cosa ne è stato di Alvarion.>\n\nAlmeno so che a Valanaar sarà al sicuro.\n\n<Straniero/Straniera>, mi dispiace dirtelo, ma credo che quell'idiota di mio marito ti abbia mandato qui a morire per niente. Se hai un minimo di buon senso, dovresti andartene subito. Questa non è la tua battaglia.", 0xa8fc6a6e, 0x914a33e3, 0x14a8cf7d, 0xefd01bb9, 0x793bb808, "....." },
  [92682] = { "Renditi utile", "Raccogli 10 Ripe Stormapple e uccidi 5 Hungry Bandit al ⟦Windfield Orchard=Frutteto di Campovento⟧.", "Oh, quindi hai più coraggio che giudizio, eh? Va bene, non discuto.\n\nFerauu e i suoi scagnozzi non devono ancora passare a ritirare la loro parte del raccolto, quindi ti metterò al lavoro in cambio dei pasti finché non arrivano.\n\nEsci e raccogli per me gli stormapple di oggi. Ah, e i banditi che si aggirano intorno agli alberi di stormapple... credono di essere furtivi. Non lo sono. Uccidili per me.\n\nVediamo cosa sai fare in combattimento.", "Questi banditi sono più propensi a tradirsi e derubarsi a vicenda che a derubare la gente comune. Scommetto che se Ferauu sapesse che alcuni dei suoi hanno fatto di testa loro e sono venuti qui in anticipo a mettere le mani sul raccolto, li ucciderebbe lui stesso.", "Ti ho visto abbattere quei banditi dalla finestra. Niente male.", 0x465218e3, 0x7a8714e9, 0x7b15cb2a, 0x836efca1, 0xe39119c4, "....." },
  [92683] = { "Polvere di flutterfly", "Raccogli 5 ⟦Flutterfly Dust=Polvere di Svolazzina⟧ dai Flutterfly nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Avrai notato i flutterfly giganti nei campi esterni vicino al frutteto, no? Sono belli da vedere, ma hanno anche altri pregi, cioè la polvere delle loro ali. Sporca un po', ma se riesci a raccoglierne in grandi quantità ha utili impieghi domestici.\n\nPrendi questo ⟦Flutterfly Swatter=Scacciasvolazzine⟧ e dai a quei grossi insetti una bella botta per me. Di solito si spaventano e scappano, ma a volte se la prendono. In ogni caso, scuoteranno il sedere e lasceranno cadere un mucchio di polvere.", "Di solito i flutterfly sono docili e tranquilli, ma se li prendi per il verso sbagliato a volte ti sorprendono.", "Questa roba sporca un po' e tende a finire dappertutto. Purtroppo te la scrollerai dai pantaloni per settimane. Però ti ringrazio davvero. Ce l'avevo nella lista delle cose da fare da settimane, ma allontanarmi troppo da casa quando sono sola e i banditi sono in agguato ovunque è un bel rischio.\n\nNon chiedermi a cosa mi serve questa roba. Cose. Roba e cose. Non preoccuparti.", 0xebc0dbf4, 0x62baa758, 0x70511ad5, 0x17b2b4fc, 0x3c26d1b7, "....." },
  [92684] = { "Galestrider bisbetici, bisbeticissimi", "Raccogli 7 Lowlands Galestrider Tenderloin dagli Ornery Galestrider delle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Come se il raccolto non fosse già abbastanza scarso quest'anno, i galestrider della zona entrano nel frutteto e mi rubano gli stormapple. Te la senti di andare nei campi e sfoltirli per me?\n\nPerò fa' attenzione, <straniero/straniera>: i galestrider delle pianure sono più grossi e rabbiosi di quelli degli altopiani. Sta' all'erta. Basta un calcio ben assestato per metterti fuori gioco per sempre, se ti distrai.\n\nPortami un po' della loro carne e potrò prepararci anche un pasto caldo.", "Credo di non mangiare carne vera a cena da... be', da troppo tempo.", "Che filetti enormi! Devi aver abbattuto dei veri mostri là fuori.", 0xe003ddda, 0xac246e35, 0x00cc4ad7, 0x2e036ee0, 0x39c498db, "....." },
  [92685] = { "Le colline hanno gli occhi", "Recupera 7 Blood-Stained Bandit Mask dagli Highwayman Bandit nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "I banditi hanno accampamenti dappertutto, e ce n'è uno piccolo sulle colline appena a nord di qui. Va' lassù e comincia a spaccare crani. Se riusciamo a coglierli alla sprovvista e a eliminarli prima che vengano a prenderci, forse riequilibreremo le forze abbastanza da avere una possibilità.\n\nPortami le loro maschere. Più insanguinate sono, meglio è.", "Se riesci a portarmi abbastanza maschere da bandito, magari ci cucio una coperta e la regalo a Ferauu.\n\n<Aamelia ride fragorosamente.>", "Quando ho detto più insanguinate, meglio è, mi hai preso alla lettera. Bene. Vuol dire che hai fatto male.\n\nParlando seriamente, grazie per quello che hai fatto finora. Da settimane vago senza meta per questa fattoria, come se stessi solo aspettando la fine. Credo di cominciare a sperare di nuovo.\n\nFerauu e i suoi scagnozzi arriveranno da un momento all'altro. Non resta che uscire ad affrontarli. Che ne dici, mi accompagnerai fino alla fine?", 0x68a565d3, 0x0cc48551, 0x0d447ad8, 0x55d5b255, 0x646cb966, "....." },
  [92693] = { "Non cederemo terreno", "Parla con Aamelia Windfield quando sei <pronto/pronta> ad affrontare il capo dei banditi.", "Hai fatto molto per darci una possibilità di combattere. Anche se oggi moriremo, almeno sapremo di averci provato con tutte le nostre forze.\n\nQuesta è la tua ultima occasione, <straniero/straniera>. Se vuoi tornare a Valanaar e vivere un altro giorno, non ti biasimerei.\n\nSe invece hai davvero un debole per le cause perse, fammi sapere quando sei <pronto/pronta>. Usciremo là fuori a testa alta, e quel che sarà, sarà.", "Non ci sono abbastanza stormapple in tutta ⟦Skywall=Celaria⟧ per ripagarti di questo.", "Non... non posso credere che sia finita. Devo fermarmi a calmarmi prima che il cuore mi salti fuori dal petto.", 0x50b105ba, 0x080cc4f1, 0xdb57333a, 0x0e2208f0, 0xae67af8a, "....." },
  [92698] = { "Qual è il mio scopo?", "Parla con Aamelia Windfield del Malfunctioning Cyclone Construct.", "<Ti avvicini per cercare di sentire le parole che provengono da sotto le placche corazzate del gigantesco costrutto.>\n\n...Errore di funzione...\n\n...Domanda...\n\n...Qual è...\n\n...Funzione...\n\n<Queste parole e frasi frammentate sembrano ripetersi all'infinito. Forse qualcuno nei paraggi sa qualcosa di più su questo costrutto?>", nil, "Il costrutto? Vaga per i campi da decenni. Da quando gli elementali del vento ci hanno lasciati, credo. Alvarion sospettava che un tempo portasse i raccolti al mercato, o magari badasse al bestiame prima che qui ci fosse un frutteto. Ma potrebbe essere stato mille anni fa.\n\nUn tempo erano i Windshaper a occuparsi della manutenzione di questi costrutti. Abbiamo pensato di chiedere loro di venire a dargli un'occhiata, ma non è mai stata una nostra priorità. Di questi tempi perlopiù lo ignoriamo.", 0x241171d6, 0xd478b4f6, 0x3666770b, nil, 0x051eaa94, "...m." },
  [92699] = { "Il magistro supremo", "Trova Elaadrin Evengale a Valanaar.", "Ora che sei <arrivato/arrivata> a Valanaar, probabilmente vorrai presentarti agli altri membri dell'High Order. L'attuale magistro supremo, Elaadrin Evengale, e la sua gente operano dalla loggia all'estremità sud-orientale di Valanaar.\n\nFa' anche attenzione: qui l'High Order e i Windshaper non vanno molto d'accordo. Sta' all'erta e tieniti ben alla larga dai Windshaper. Abbiamo già abbastanza da preoccuparci con il culto: non tollererò violenze tra fazioni per le strade di Valanaar.", nil, "Salve e <benvenuto/benvenuta>. Rathiril mi ha mandato un messaggio magico su di te e ha detto che promettevi bene.\n\nOra che ti ho davanti, capisco perché ti ha suggerito di cercarmi. Hai un'aura arcana vibrante. Ormai siamo in pochi ad avere l'attitudine, per non parlare della volontà, di fare ciò che serve per salvare la nostra casa. Hai l'audacia e la forza necessarie per aiutare l'High Order?\n\nImmagino che lo vedremo.", 0x395f1c03, 0x81508f78, 0xc13b19e1, nil, 0xe177374f, "...m." },
  [92700] = { "La gran scrutacieli", "Trova Ayessa Dawnsinger a Valanaar.", "Ora che sei <arrivato/arrivata> a Valanaar, probabilmente vorrai presentarti agli altri membri dei Windshaper. L'attuale gran scrutacieli e la sua gente operano dalla loggia vicino al centro di Valanaar.\n\nE sappi anche che da queste parti i Windshaper e l'High Order non vanno molto d'accordo. Sta' all'erta e tieniti ben alla larga dall'High Order. Abbiamo già abbastanza da preoccuparci con il culto: non tollererò violenze tra fazioni per le strade di Valanaar.", nil, "L'anziana Amberwind mi ha mandato un messaggio su di te e sulle tue imprese al ⟦Shen'dar Village=Villaggio di Shen'dar⟧. Sei davvero <il/la> <benvenuto/benvenuta> qui, <amico/amica>.\n\nHai un'aura forte e sei chiaramente in sintonia con gli spiriti. Ultimamente siamo sempre meno ad avere lo skysight, e Zephras ha bisogno di chi possiede il dono se vogliamo sopravvivere a questi tempi difficili. Sono lieta che tu abbia trovato la strada fino a me.\n\nNon vedo l'ora di conoscerti meglio.", 0x0b95857e, 0x5fb884e9, 0xe4a12cfa, nil, 0xb039551c, "...m." },
  [92701] = { "Verso Valanaar", "Consegna Aonda's Written Report a Valennia Stormfist a Valanaar.", "Per ora sembra che il pilone e il villaggio siano al sicuro, quindi vorrei che portassi questo rapporto a Valennia Stormfist a Valanaar, sul margine sud-orientale dell'isola. Valennia è a capo dei Pacificatori dell'isola e deve sapere cos'è successo qui.\n\nIl culto si sta espandendo in fretta e finora i Pacificatori hanno evitato lo scontro diretto, ma quei tempi sono finiti. Valanaar dovrà essere pronta a combattere.\n\nIn ogni caso, grazie. A Shen'dar avrai sempre degli amici, {name}.", "Una lettera di Aonda. Che cosa avrà combinato quella volpe degli altopiani?", "<L'espressione di Valennia si incupisce mentre legge la lettera.>\n\nAonda ti ha affidato questa lettera e in essa parla abbastanza bene di te, quindi cercherò di fidarmi anch'io. Prima di parlare ancora, devo consultarmi con i pochi Pacificatori che mi restano qui e preparare un piano nel caso il culto colpisca qui la prossima volta. Per ora goditi il soggiorno a Valanaar.\n\nSe cerchi qualcosa da fare, ci sono molti abitanti che probabilmente avrebbero bisogno dell'aiuto di <un/una> giovane <avventuriero/avventuriera> forte come te.", 0x74fef55e, 0x117fb641, 0x1bb0140d, 0xc4bd4279, 0xd674e12c, "....." },
  [92702] = { "Allungare i rami", "Trova un ramo robusto che arrivi fino a Fenwick Mollascatto.", "<Fenwick si sforza di dondolarsi avanti e indietro per prendere un po' di slancio.>\n\nEhi! Ehi, tu! Prendi un bastone e vedi se riesci a raggiungermi, per favore? Sono bloccato qui da così tanto tempo che le bretelle mi danno fastidio! Ho cose buone, cose OTTIME da condividere con te! Fenwick Mollascatto non fa mai false promesse!\n\nÈ mio fratello arrugginito, laggiù alla piattaforma di lancio, che ha chiaramente sbagliato qualche calcolo sulle capacità di lancio del nostro razzo! È lui il signor false promesse!\n\n<Fenwick non riesce ad afferrare un oggetto fuori dalla sua portata.>", nil, nil, 0x069ff6c7, 0xf25f0e10, 0x97234499, nil, nil, "...mm" },
  [92703] = { "Portare la notizia", "Parla con Alvarion Windfield a Valanaar.", "Dopo tutto questo non mi sembra giusto continuare a chiamarti <straniero/straniera>, quindi... grazie, {name}.\n\nSe non ti dispiace e torni da quelle parti, fai sapere ad Alvarion cos'è successo qui. E digli anche che, appena si sarà rimesso in piedi, deve portare qui un Windshaper a esaminare quel costrutto, per essere sicuri che sia prudente tenerlo vicino alla nostra... alla nostra famiglia.\n\n<Aamelia si sfiora delicatamente il ventre.>\n\nDi questo lui non sa niente. Teniamolo tra noi, per ora.", nil, "<Gli occhi di Alvarion si riempiono di lacrime mentre finisci di raccontare cos'è successo al frutteto.>\n\nNon so come ringraziarti, <amico/amica>. Sono venuto a Valanaar in cerca di speranza. Una speranza vana, ne ero quasi certo. E invece ho trovato <un/una> <eroe/eroina>. <Un/Una> <vero/vera> <eroe/eroina>, come nelle storie di prima che venissimo a ⟦Skywall=Celaria⟧.\n\nNon dimenticherò mai ciò che hai fatto per noi, {name}. Sarai sempre <il/la> <benvenuto/benvenuta> a casa Windfield.", 0xa7d041e9, 0xd93e176f, 0x41c99c84, nil, 0x57d677d5, "...m." },
  [92706] = { "RICERCATO: Bruuz", "Porta Bruuz's Dorsal Fin a ⟦Gazlowe=Sparachiodi⟧ a ⟦Ratchet=Porto Paranco⟧.", "Avviso a tutti i pescatori!\n\nUno squalo gigante si aggira nelle acque vicino al molo di carico, attaccando marinai e piccole barche. Gli scaricatori gli hanno dato il soprannome di \"Bruuz\". Una lauta ricompensa a chi mi porterà la sua pinna!\n\n-- ⟦Gazlowe=Sparachiodi⟧", "Che posso fare per te, {race}?", "Finalmente qualcuno ha fatto fuori quella bestia! Sai quanto è difficile mettere in acqua una ciurma quando tutti in città gridano \"Squalo!\" in continuazione?\n\nQuasi quasi stasera metto la pinna di quel mostro in una zuppa per cena, giusto per ridere per ultimo.", 0x63f4d985, 0xf267f662, 0xc0d6b34c, 0x98361c3d, 0x67d0abe8, "....." },
  [92707] = { "Il gigante nella tana", "Porta Goliath's Wristguards a Drum Fel a ⟦Hammerfall=Requie del Martello⟧.", "Strappati dal suo enorme cadavere, i bracciali del golia sono immensi. Puoi infilarci tutto il braccio, fino alla spalla, senza toccare i bordi.\n\nDovresti riportarli a ⟦Hammerfall=Requie del Martello⟧, come avvertimento. Drum Fel deve sapere con cosa ha a che fare.", nil, nil, 0x97265d43, 0x8a910368, 0x97fb37e9, nil, nil, "...mm" },
  [92708] = { "Una grande avventura", "Ascolta ciò che Ayessa Dawnsinger ha da dirti.", "I Windshaper si stanno dando un gran da fare per rispondere alla crisi che colpisce l'isola di Zephras. Nella nostra ricerca degli spiriti del vento scomparsi abbiamo fatto diverse scoperte sorprendenti, e stiamo preparando un piano d'azione che potrebbe darci i mezzi per salvare l'isola.\n\nPerché funzioni, però, ci serviranno giovani avventurieri forti come te. Ti prego, se hai un momento, parliamone ancora.", nil, "Ora capisci? Fuori da ⟦Skywall=Celaria⟧ c'è un mondo di conoscenza e di potenziale inesplorato. Questa non smetterà mai di essere la nostra casa, ma mi sono convinta che la via della nostra salvezza si trovi in basso. Dobbiamo andare su Azeroth e ottenere il potere e i mezzi per salvare l'isola di Zephras. Questa è la via.\n\nAvrai il coraggio di unirti a noi quando sarà il momento?", 0xd900e63a, 0x9a2edad6, 0x4a6064f1, nil, 0x1a982773, "...m." },
  [92709] = { "Una grande avventura", "Ascolta ciò che Elaadrin Evengale ha da dirti a Valanaar.", "Il tuo lignaggio degli Alti Nobili risplende nei tuoi occhi, chiaro come il cielo sopra di noi. Sei dei nostri, e sono i giovani come te che ci aiuteranno a salvare la nostra casa. Ma prima lascia che ti racconti di più della nostra missione e dei nostri piani qui su Zephras... e oltre.", nil, "Ora capisci? Riscoprire l'antica magia dei nostri antenati è la chiave per svelare i segreti dell'isola di Zephras e assicurarci un futuro, ma per salvare la nostra casa dobbiamo riscoprire ciò che abbiamo perso in questi millenni.\n\nAzeroth è la chiave. Il Kirin Tor ci mostrerà la via.\n\nMentre ci prepariamo a partire, dovresti presentarti agli altri membri dell'High Order qui a Valanaar. Quasi tutti hanno compiti per cui l'aiuto di qualcuno come te farebbe comodo.", 0xd900e63a, 0x8e1740b2, 0x2d2692fd, nil, 0x7ee53658, "...m." },
  [92727] = { "Lo studioso scomparso", "Scopri che fine ha fatto Fillion Flamebreeze.", "Cercare la conoscenza è il mandato principale dell'High Order, ma questo lavoro non è mai stato tanto pericoloso quanto lo è oggi su Zephras.\r\n\nUno dei nostri studiosi, Fillion Flamebreeze, era in viaggio verso gli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧ per raccogliere dati sulla magia portata dal vento che si concentra in alcune zone della regione. Purtroppo non è tornato, e temiamo che gli sia successo qualcosa lungo la strada.\r\n\nSe puoi, trovalo per noi. È stato visto l'ultima volta sulla strada che da Valanaar va verso ovest, in direzione degli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", nil, "<La bisaccia che hai davanti ha sulla patta qualche macchiolina di quello che sembra sangue secco. Esaminando la macchia, noti anche che sulla patta è ricamato un nome. Dice «Fillion Flamebreeze».>", 0xa1e8590e, 0xd1671205, 0x24478d54, nil, 0x34292c36, "...m." },
  [92741] = { "Visitatori sgraditi", "Va' nella ⟦Shadowgale Forest=Foresta di Ventombra⟧ e raccogli 8 ⟦Shriekling Talons=Artigli di Strillino⟧ per Iaadaria Bitterwind a Valanaar.", "La ⟦Shadowgale Forest=Foresta di Ventombra⟧ è estremamente pericolosa e di solito è interdetta ai normali avventurieri. Negli ultimi mesi la popolazione degli shriekling è esplosa e hanno cominciato a estendere il loro territorio fuori dal bosco, il che potrebbe diventare un problema. Mi interessano le proprietà alchemiche degli artigli di shriekling, quindi un abbattimento quanto mai necessario è anche un'occasione di guadagno per i nostri studi.\r\n\nVa' nella ⟦Shadowgale Forest=Foresta di Ventombra⟧ e caccia quelle bestie. Portami quanti più artigli puoi.", "L'High Order non ha l'abitudine di prestarsi come semplici trappolieri e guardacaccia, ma quando un servizio come questo può portare vantaggi agli studi, siamo lieti di dedicarci a opere di utilità per la comunità.", "Che bel bottino di artigli mi hai portato. Non vedo l'ora di studiarli!\r\n\nGrazie per il tuo servizio all'High Order, {class}.", 0x3ef89823, 0xc2afbc22, 0x9ce8f981, 0x285f2c2b, 0x798df088, "....." },
  [92742] = { "Analisi dei pozzi", "Usa il ⟦Well Water Sample Kit=Kit di Campionamento dell'Acqua di Pozzo⟧ per prelevare campioni dai pozzi della Cascina dei Jansen e della Fattoria dei Molsen.", "Dobbiamo scoprire l'origine e la natura del veleno che corrompe questa terra. Cominciamo dalle acque sotterranee sotto le fattorie della zona.\r\n\nVa' alla Cascina dei Jansen, a nord, e alla Fattoria dei Molsen, a nord-ovest di qui, e preleva dei campioni dai loro pozzi.", "Hai raccolto i campioni?", "Grazie. Vediamo un po'...", 0x1754ed02, 0xbfaa968d, 0x8ee73e39, 0xf98dff5c, 0x9913f7d5, "....." },
  [92743] = { "L'⟦Conqueror's Crown=Elmo del Conquistatore⟧", "Mantieni la tua reputazione presso i Magram e porta un ⟦Conqueror's Crown=Elmo del Conquistatore⟧ dalle ⟦Badlands=Maleterre⟧ a Warug al Magram Village.", "Come clan di centauri più forte di tutta la terra, meritiamo armi con una ferocia pari alla nostra forza!\r\n\nWarug ne ha bisogno più di tutti. Un elmo... no, una corona! Una corona da conquistatore! Ho sentito leggende su un temibile conquistatore oltre i mari. Va' in un posto che chiamano ⟦Badlands=Maleterre⟧ e cerca una cripta. Torna da me solo quando avrai trovato la corona.\r\n\nFallo per me, e ti rivelerò la più grande forza dei Magram.", "Niente elmo, niente discorso!", "Guarda qua! Guardalo! Che elmo! Degno di un Khan... ma destinato a essere indossato da Warug. Sono compiaciuto.\n\nSei pront<o/a> a conoscere la nuova arma dei Magram contro i nostri nemici?", 0x113cbd89, 0xdd9d5673, 0x785d75a9, 0x55b80b6d, 0x0841d7e7, "....." },
  [92744] = { "Branchie di murloc", "Alba Fairmoon vuole che tu raccolga 7 Longshore Murloc Gill lungo la costa delle ⟦Westfall=Marche Occidentali⟧.", "La corruzione che colpisce i raccolti delle Marche Occidentali potrebbe essere filtrata anche nell'oceano. Se anche i pesci della zona ne sono colpiti, ⟦Stormwind=Roccavento⟧ potrebbe essere condannata alla carestia.\r\nRaccogli le branchie dei murloc lungo la costa e portamele. I murloc sono piuttosto resistenti, ma la loro fisiologia è estremamente sensibile alle sostanze contaminanti. Qualunque tossina nell'acqua di mare sarà subito evidente nelle branchie che troverai.", "I murloc non ti hanno dato troppi problemi, spero?", "Capisco... queste branchie sembrano sane, per ora. Ma non dobbiamo abbassare la guardia.", 0x18d085b1, 0x82b38f95, 0x84c4b3d3, 0xebb50726, 0x6a17bd1b, "....." },
  [92745] = { "Lo stato delle miniere", "Uccidi 4 Kobold Digger nella ⟦Jangolode Mine=Miniera Venacava⟧ e 6 Riverpaw Miner nella ⟦Gold Coast Quarry=Cava della Costa d'Oro⟧.", "I campioni dei pozzi che hai raccolto contengono metalli tossici! Se non mettiamo fine in fretta a questa corruzione, passeranno decenni prima che in questo suolo possano crescere di nuovo dei raccolti.\r\nI Defias si sono impadroniti delle miniere delle ⟦Westfall=Marche Occidentali⟧ e usano delle creature come manodopera per spogliarle delle loro risorse. Ostacolali uccidendo i loro minatori nella ⟦Jangolode Mine=Miniera Venacava⟧, a nord, e nella ⟦Gold Coast Quarry=Cava della Costa d'Oro⟧, a ovest.", nil, "Ben fatto, {name}. Ma temo che l'origine del veleno si trovi altrove...", 0xdbfbda3d, 0xb4f30bb0, 0x0ed0182f, nil, 0x1b6794e0, "...m." },
  [92747] = { "Spionaggio a ⟦Moonbrook=Rivoluna⟧", "Raccogli 8 ⟦Suspicious Industrial Supplies=Materiali Industriali Sospetti⟧ a ⟦Moonbrook=Rivoluna⟧.", "Strano: il veleno non sembra provenire dalle miniere che hai esaminato.\r\n\nMi dicono che le ⟦Deadmines=Miniere della Morte⟧, sotto il villaggio di ⟦Moonbrook=Rivoluna⟧, siano le miniere più grandi e profonde delle ⟦Westfall=Marche Occidentali⟧, ma sono abbandonate dai tempi della Prima Guerra. Possibile che le ⟦Deadmines=Miniere della Morte⟧ siano di nuovo in attività?\r\n\nVa' a ⟦Moonbrook=Rivoluna⟧, {name}, e cerca prove di attività minerarie o industriali. È l'ultima pista che abbiamo!", "Hai trovato qualcosa?", "Che cos'è tutta questa roba?", 0xd607718d, 0x576e6434, 0xbc34590a, 0x2e14d88f, 0xb7fab352, "....." },
  [92748] = { "Una consulenza esplosiva", "Va' nel Distretto dei Nani di ⟦Stormwind=Roccavento⟧ e trova un ingegnere che possa aiutarti.", "Le provviste che hai trovato indicano un'enorme attività industriale da qualche parte nelle ⟦Deadmines=Miniere della Morte⟧. Non c'è dubbio che sia questa l'origine delle tossine che affliggono i campi delle ⟦Westfall=Marche Occidentali⟧. Dobbiamo fermarla, e in fretta.\r\n\nQualunque cosa ci sia laggiù, sarà difficile da distruggere. Va' nel Distretto dei Nani di ⟦Stormwind=Roccavento⟧ e trova un ingegnere che possa procurarci degli esplosivi.", nil, "Hai bisogno di far saltare in aria qualcosa?", 0x35aa9cd8, 0x37ec6835, 0x6c61d133, nil, 0x8969accc, "...m." },
  [92749] = { "Un piano a base di dinamite", "Procurati $N1 ⟦Rough Dynamite=Dinamite Grezza⟧ con la creazione, gli scambi o la casa d'aste, poi torna da ⟦Sprite Jumpsprocket=Sprite Giramolla⟧ nel Distretto dei Nani di ⟦Stormwind=Roccavento⟧.", "Sabotaggio industriale? Hai tutta la mia attenzione!\r\nCominceremo con un po' di dinamite...", "Fammi vedere quegli esplosivi, {name}!", "È un ottimo inizio! Ora mettiamo tutto insieme... e aggiungiamo un pizzico di brio in più...", 0xdbe7a3f6, 0x63fc4165, 0x9f9816fe, 0x9f4c0c1a, 0xb7dd7511, "....." },
  [92750] = { "Detonazione a distanza", "Parla con qualcuno dei servizi segreti di ⟦Stormwind=Roccavento⟧ per procurarti un detonatore a distanza.", "Immagino tu voglia un'esplosione «controllata»? Meno divertente, ma una buona scelta se vuoi tenerti tutti gli arti.\r\nTemo di non avere un detonatore a distanza... perché non chiedi a quei tipi furtivi dei servizi segreti di ⟦Stormwind=Roccavento⟧? Dovrebbero riuscire a trovarci qualcosa.", nil, "Mmh... Cerchi qualcosa di preciso, vero?", 0x9e430b80, 0x2e22edaa, 0xe691f760, nil, 0xe2f54704, "...m." },
  [92751] = { "Detonazione a distanza", "Porta il ⟦Remote Detonator Kit=Kit Detonatore a Distanza⟧ a ⟦Sprite Jumpsprocket=Sprite Giramolla⟧ nel Distretto dei Nani di ⟦Stormwind=Roccavento⟧.", "Ti serve distruggere qualcosa? Ha forse a che fare con le tue attività a ⟦Moonbrook=Rivoluna⟧? Non fare quella faccia sorpresa. L'⟦SI:7=IR:7⟧ è sempre al corrente di tutto ciò che accade nelle terre di Roccavento.\r\n\nSe hai intenzione di provocare un'esplosione nelle grotte sotto le ⟦Westfall=Marche Occidentali⟧, ti conviene essere ben lontan<o/a> prima. Prendi questo detonatore a distanza: è un prototipo recente dei nostri ingegneri.\r\n\nAh, e sarebbe meglio che non parlassi del mio coinvolgimento alla tua amica elfa.", "Hai preso un detonatore a distanza? Uno normale non andrà bene!", "Perfetto, è proprio quello che ci serve!", 0x9e430b80, 0xecf85250, 0xc3fa1845, 0xb686a7e4, 0xa8ffd86b, "....." },
  [92752] = { "Una consulenza esplosiva", "Torna da Alba Fairmoon nelle ⟦Westfall=Marche Occidentali⟧.", "Ecco fatto: la bomba è pronta! E ora attenzione con quel detonatore.", "I tuoi sforzi a ⟦Stormwind=Roccavento⟧ sono stati fruttuosi?", "Che piacere rivederti, {name}.", 0x35aa9cd8, 0x767de34f, 0xeac04347, 0xdf96f53e, 0x10bfbc2a, "....." },
  [92753] = { "Distruzione nelle ⟦Deadmines=Miniere della Morte⟧", "Trova la forgia nascosta nelle ⟦Deadmines=Miniere della Morte⟧ e piazza lì vicino gli ⟦Extra-Destructive Explosives=Esplosivi Extra-distruttivi⟧. Poi raggiungi Alba Fairmoon all'uscita delle ⟦Deadmines=Miniere della Morte⟧.", "L'origine del veleno è probabilmente una grande forgia metallurgica di qualche tipo. Trova un modo per entrare nelle ⟦Deadmines=Miniere della Morte⟧, individua la forgia e piazza gli esplosivi.\r\nTi aspetterò sulle colline dietro ⟦Moonbrook=Rivoluna⟧. Quando tornerai, potremo far esplodere le cariche. Con un po' di fortuna, senza la forgia, la terra potrà cominciare a guarire.", "Ora tutto dipende da te, {name}.", "Quindi hai trovato la forgia e piazzato la bomba... resta da fare una sola cosa.", 0x7e9a4fff, 0x13b8e5d8, 0xc733c35a, 0x168876a5, 0x52da3fc0, "....." },
  [92754] = { "Un nuovo bisogno di ⟦Shadow Protection=Difesa dall'Ombra⟧", "Mantieni la tua reputazione presso i Magram e porta $N1 Pozione Superiore della ⟦Shadow Protection=Difesa dall'Ombra⟧ a Mirda al Magram Village, a ⟦Desolace=Desolanda⟧.", "I nostri compagni di clan continuano a spingersi più a sud, fino alla maledetta ⟦Valley of Bones=Valle delle Ossa⟧ e oltre.\r\n\nNonostante la tua posizione presso il nostro clan, non mi fido abbastanza di te da rivelarti i dettagli delle loro spedizioni. Tanto ti annoierebbero, <straniero/straniera>.\r\n\nCiò che conta per te è che ci servono Pozioni Superiori della ⟦Shadow Protection=Difesa dall'Ombra⟧, in gran quantità, per garantire la loro sopravvivenza. Portamene un po' e metterò una buona parola per te.", nil, nil, 0x687ae999, 0xb5521b2f, 0xa57a9cc9, nil, nil, "...mm" },
  [92755] = { "Misticismo misterioso", "Mantieni la tua reputazione presso i Gelkis e porta $N1 Greater Mystic Essence a Halea al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧.", "Ogni giorno che passa, i nostri razziatori tornano con sempre meno armi prese agli avventurieri caduti.\r\n\nNon possiamo usare direttamente questi pezzi, ma li recuperiamo per ricavarne materiali. I più magici finiscono a me, perché posso disincantarli e usare i misteriosi residui per incantare le nostre armi, in particolare quelle dei nostri windchaser.\r\n\nMi servono delle Greater Mystic Essence, se devo fornire alla prossima spedizione di razzia un equipaggiamento che valga qualcosa.", nil, nil, 0x7a268f3c, 0xe6a3f066, 0x69bc1d33, nil, nil, "...mm" },
  [92811] = { "Guerra economica", nil, nil, "Una cosa che la guerra ci ha insegnato: il denaro è potere.\n\nTutti i centauri di ⟦Desolace=Desolanda⟧ hanno concordato di barattare con legno intagliato con cura, che racconta la gloria e le conquiste del singolo centauro. È l'unica tregua dalla battaglia, e solo i più posati possono trattare con gli altri clan.\n\nHo visto la tua gente commerciare in oro e argento. Per noi non valgono nulla, come per voi i nostri totem. Portamene alcuni e il clan Magram ne sarà lieto.", "Una saggia decisione, forestiero. La tua generosità non passerà inosservata.", 0x5319cccc, nil, nil, 0xb71fa9c3, 0xf1cec9dc, ".mm.." },
  [92812] = { "Guerra Economica", nil, nil, "Tanto tempo fa, tutti i clan di centauri di ⟦Desolace=Desolanda⟧ accettarono di commerciare in storie. Più precisamente, in totem intagliati che rappresentano le grandi imprese di un individuo o di un clan. Nonostante il conflitto senza fine, tutti i clan continuano a onorare questa tradizione, anche se le occasioni di scambio tra noi si sono fatte sempre più rare.\n\nSe ne trovi qualcuno, per esempio sui centauri caduti degli altri clan, portamelo. Ai Gelkis farebbe comodo un po' di potere contrattuale in più, e informerò il Khan del tuo aiuto.", nil, 0x5319cccc, nil, nil, 0x95051ff3, nil, ".mm.m" },
  [92814] = { "Mi serve un sarto", "Mantieni la tua reputazione presso i Gelkis e porta una ⟦White Bandit Mask=Maschera del Bandito Bianca⟧ a Molkar al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧.", "La mia compagna, Halea, ha il compito di assicurarsi che le nostre armi siano potenziate con l'energia magica adatta.\r\n\nL'intero concetto di incantamento va ben oltre la mia comprensione, ma, come centauro incaricato di tenere il nostro villaggio ben rifornito ed equipaggiato, so che Halea è spesso in ritardo con i suoi compiti, e non per colpa sua.\r\n\nVorrei regalarle dei semplici indumenti su cui esercitare la sua arte. Vedo alcuni avventurieri girare nelle tempeste di sabbia con semplici maschere sul viso. Potresti procurarmene qualcuna?", nil, nil, 0xd86e3465, 0x683448f5, 0x2e330903, nil, nil, "...mm" },
  [92817] = { "La tecnica del conciatore", "Mantieni la tua reputazione presso i Gelkis e porta un'⟦Barbaric Harness=Imbracatura della Barbarie⟧ a Talra al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧.", "Convincere i miei compagni di clan Gelkis a indossare un'armatura è quasi impossibile, nonostante le numerose perdite che abbiamo subito per lame o dardi nel petto.\r\n\nMi è stato affidato il compito di progettare un corpetto che offra una protezione ragionevole, senza il presunto «prurito» di cui si lamentano. Le provviste scarseggiano, quindi non oso sprecare del cuoio prezioso in robaccia.\r\n\n<Straniero/Straniera>, mi porteresti un'imbracatura adatta a un centauro rozzo? Vorrei imparare dalla tua tecnica.", nil, nil, 0xe1654f2c, 0x78d11657, 0xe5dbca65, nil, nil, "...mm" },
  [92818] = { "Asce di ferro grandi, anzi, MASSICCE", "Mantieni la tua reputazione presso i Magram e porta $N1 Ascia Massiva di Ferro a Grolkar al Magram Village, a ⟦Desolace=Desolanda⟧.", "CI SERVONO PIÙ ARMI.\r\n\nPIÙ. ARMI.\r\n\nIN CHE ALTRO MODO I MAGRAM SCHIACCERANNO I GRACILI GELKIS?\r\n\nVOGLIO VEDERE COSA SAI FARE, <STRANIERO/STRANIERA>. PORTAMI DELLE ASCE. GRANDI, ANZI, MASSICCE.\r\n\nSBRIGATI.", nil, nil, 0x1c3f85ce, 0x4f5d09f2, 0xdfe891b2, nil, nil, "...mm" },
  [92819] = { "Distruzione nelle ⟦Deadmines=Miniere della Morte⟧", "Usa il detonatore.", "Ci siamo quasi. Usa il detonatore e metti fine a tutto questo.", nil, "Non so cosa dire, {name}. Pensare che ⟦Stormwind=Roccavento⟧ metterebbe le proprie ambizioni militari davanti al sostentamento della sua gente...", 0x7e9a4fff, 0x8e3775bb, 0x06a779b6, nil, 0x527c6a4f, "...m." },
  [92833] = { "La caduta di Ve'han", "Usa il Bastone della Montagna per privare Ve'han Presartiglio del suo potere rubato, poi distruggilo.", "Ve'han ora rivendica il Padiglione di Nordrassil, sotto i rami del grande albero, come suo covo. È giunto il momento di mettere questa magia alla prova suprema.\n\nPrendi il bastone e usalo contro Ve'han. Dissolvi la magia che lo protegge e consegnalo alla giustizia!", nil, nil, 0x04de11fc, 0xb91fdb94, 0x733b8ff6, nil, nil, "...mm" },
  [92834] = { "Vendicato al decuplo", "Raccogli 10 Al'Aketh Windstone Charm dai cultisti Al'Aketh che si trovano a nord di Valanaar, nei Gustberry Fields o al ⟦Shrine of Akir=Sacrario di Akir⟧.", "Quando il culto ha cominciato la sua campagna di violenza, i Pacificatori e i Windshaper hanno risposto mostrando i muscoli. Lo consideravo un'inutile escalation, così ho sostenuto il dialogo pacifico. Ieri ho mandato il mio amico Belathaan Brightwish al ⟦Shrine of Akir=Sacrario di Akir⟧, sperando di avviare quel dialogo.\r\n\nÈ appena arrivata una scatola con dentro la lingua di Belathaan, intinta di pigmento argentato.\r\n\nOra mi è chiaro che con il culto non si può ragionare. Uccidi tutti i cultisti che vedi e portami gli amuleti di preghiera che portano con sé.", "Non mi trovo spesso d'accordo con i Windshaper, ma avevano ragione a scartare l'idea di cercare un confronto pacifico con gli Al'Aketh. Il mio tentativo di scegliere la via più nobile è costato la vita a un caro amico, ed è un errore con cui dovrò convivere per il resto dei miei giorni.", "L'High Order si vanta del suo pragmatismo e della sua logica, e la logica impone che evitare il conflitto e la perdita di vite sia, nella maggior parte dei casi, la scelta più prudente.\r\n\n<Gli occhi di Elaadrin cominciano a brillare e a crepitare di energia arcana.>\r\n\n...tuttavia, il culto ha scambiato la nostra prudenza per debolezza, e non è affatto pronto a pagare il prezzo di quell'errore.", 0xe040942e, 0xd3397555, 0x7ba9539f, 0x93e0875d, 0x12ebcdcd, "....." },
  [92840] = { "Catturare il vento", "Porta l'Index Esoteria alle ⟦Overlook Standing Stones=Pietre Erette del Belvedere⟧ negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧ e usalo sulle Windstone Formation della zona per raccogliere dati.", "Fillion era stato mandato alle ⟦Overlook Standing Stones=Pietre Erette del Belvedere⟧ con uno speciale dispositivo che serve a misurare e studiare l'energia elementale di quel luogo.\r\n\nPrendi questo, un Index Esoteria, e usalo per estrarre dati dalle enormi formazioni di pietra del vento che si ergono lì. Stai in guardia, però: è probabile che ora i Windshaper sorveglino gelosamente quel sito.\r\n\nSe qualcuno cerca di ostacolarti, be'... fa' ciò che devi. Non ho più pazienza per le loro interferenze.", "Spesso mi è difficile distinguere i Windshaper dagli Al'Aketh, se non per il fatto che gli uni sono più apertamente violenti degli altri. Ugualmente schiavi delle loro convinzioni malriposte, sono entrambi altrettanto pericolosi se lasciati a se stessi.\r\n\nVedono il nostro desiderio di comprendere meglio questo regno e la sua magia come una profanazione delle loro tradizioni. La loro ristrettezza mentale è il motivo per cui la nostra missione è così importante. Se non noi, chi avrà il coraggio di salvare Zephras?", "Non avrei voluto versare sangue Windshaper, ma la colpa di questo inutile conflitto ricade soltanto su di loro. Noi cercavamo di raccogliere informazioni in modo pacifico, e loro hanno risposto con la violenza.\r\n\nPurtroppo la voce si è sparsa e i Windshaper lo chiamano già un «massacro». Non oserebbero vendicarsi qui a Valanaar, ma di certo non dimenticheranno.\r\n\n{name}, sei stat<o/a> di enorme aiuto all'High Order. Grazie.", 0x24fe5981, 0x3d378073, 0x1389f90b, 0x5ad6771e, 0x6f9df3cd, "....." },
  [92841] = { "La ⟦Valley of Bones=Valle delle Ossa⟧", "Migliora la tua reputazione presso i Magram e trova Orgrul vicino alla ⟦Valley of Bones=Valle delle Ossa⟧, a sud del Magram Village.", "È giunto il momento, <straniero/straniera>, che tu sappia della nostra grande scoperta... ma non sarà Warug a raccontartela!\r\n\nVa' a sud, all'altro capo del villaggio. Cerca un centauro grosso e puzzolente di nome Orgrul.\r\n\nLo capirai quando arriverai.\r\nLo capirai quando lo vedrai.\r\nSe pensa che tu meriti di saperlo, lo saprai.\r\n\nE se non lo pensa? Be'. Potrai consolarti sapendo che Warug ha una corona nuova.", nil, "Quindi le voci sono vere. Peccato che Warug ti abbia fatto correre in giro con compiti frivoli. Almeno hai dimostrato il tuo valore.\n\nSbircia giù nella valle: cosa vedi? Ossa e cadaveri. Non morti vaganti. E i Golia Gemelli.\n\nQuesto luogo era maledetto molto prima del nostro arrivo, e sospetto che resterà tale per molte generazioni. Il nostro clan è stato il primo ad affrontare gli orrori laggiù, e sarà l'unico a rivendicarne il potere.\n\nHai fame quanto me di dominare tutta ⟦Desolace=Desolanda⟧?", 0x1c23f49e, 0xe0ffefcb, 0xea834bb9, nil, 0x96b75983, "...m." },
  [92842] = { "Un cugino all'estero", "Trova il cugino scomparso da qualche parte sul ⟦Mount Hyjal=Monte Hyjal⟧.", "Ho un cugino che, tempo fa, ha accennato a un piano per visitare il ⟦Mount Hyjal=Monte Hyjal⟧ e vedere cosa vi sta accadendo. Una follia.\n\nHyjal è dall'altra parte del mondo; la posta potrebbe impiegare mesi per raggiungerlo, ammesso che trovi una cassetta delle lettere.\n\nNel caso improbabile in cui tu ti trovassi da quella parte del mondo, apprezzerei che qualcuno desse un'occhiata a quello sciocco di mio cugino.", nil, nil, 0xad20a851, 0x71fdca5e, 0xc37e7db9, nil, nil, "...mm" },
  [92844] = { "Una montagna di ossa", "Mantieni la tua reputazione presso i Magram e porta $N1 Gently Cursed Bone a Orgrul, a sud del Magram Village, a ⟦Desolace=Desolanda⟧.", "Una sorta di energia negromantica ha permeato tutta la ⟦Valley of Bones=Valle delle Ossa⟧, per ragioni che ancora non comprendiamo.\r\n\nQuelle ragioni, del resto, non ci interessano. Ora la magia è nostra, e chi non combatte con la lama o con la mazza viene addestrato in questa nuova magia.\r\n\nSe pensi che intenda cominciare con un compito impegnativo, ripensaci. Per ora, va' nella ⟦Valley of Bones=Valle delle Ossa⟧ e procurami delle ossa. Sono sicuro che te la caverai.", "Per ogni osso che ti manca per il compito, ne prenderò uno dei tuoi per colmare la differenza.", "<Orgrul comincia a contare le ossa, ma inizia a saltare i numeri quando acquistano una seconda cifra e alla fine perde il conto. Ci riprova, ma a un certo punto ti lancia un'occhiataccia quando la tua espressione si contorce mentre osservi.>\n\nBah. Le conterò più tardi. Sembrano abbastanza. Faresti meglio a non ingannarmi.\n\nLe tengo io.", 0x87f6217c, 0x119ae063, 0xf8d93bb4, 0x41e72034, 0xba106473, "....." },
  [92846] = { "Negromanti esiliati", "Mantieni la tua reputazione presso i Magram e uccidi gli Outcast Necromancer nella ⟦Valley of Bones=Valle delle Ossa⟧.", "Hai notato i gracili centauri che vanno in giro scalpitando da queste parti? Sono di stirpe Gelkis.\r\n\nNoi Magram ci siamo già assicurati un punto d'appoggio più in profondità nel canyon. Quando i Gelkis si sono accorti della nostra presenza qui, alcuni di loro hanno scelto di seguire le nostre orme. Non so se vogliano unirsi a noi o tentare di rovesciarci, ma so che i loro compagni di clan li hanno condannati tutti all'esilio.\r\n\nSono lupi solitari che si immischiano in poteri che non appartengono loro. Li voglio morti.", nil, "Bwahaha, ho sentito le loro grida da qui!\n\nI Gelkis dovrebbero imparare a massacrare i loro stessi consanguinei che tradiscono la loro eredità. Non farlo ci lascia l'onere di ripulire il loro pasticcio, e io non sono qui per rassettare dopo un clan inferiore.\n\nSe ne vedi altri, assicurati di spegnere la luce nei loro occhi. Una volta un Gelkis, sempre un Gelkis.", 0xfacd5ea6, 0xf4045ba9, 0xed11a5fa, nil, 0x7523353c, "...m." },
  [92847] = { "Lacrime corruttrici", "Mantieni la tua reputazione presso i Magram e riporta $N1 ⟦Petrified Bark=Corteccia Pietrificata⟧ e $N2 ⟦Imbued Tears=Lacrime Infuse⟧ a Orgrul.", "<Straniero/Straniera>, hai notato l'arma che i negromanti esiliati tenevano in mano? Faremo in modo che i Gelkis non vivano abbastanza a lungo da padroneggiare le vie della negromanzia, ma i loro metodi di incanalamento hanno attirato la mia attenzione. Usano perfino quegli stessi cristalli che Warug ti ha chiesto di rubare.\r\n\nCredo che possiamo sfruttare questa tecnica a nostro vantaggio. Torna nella valle a recuperare del legno dagli alberi maledetti, e vedi se Warug è disposto a cederti qualcuno dei suoi cristalli. Ne ricaverò dei bastoni.", "Questi bastoni potrebbero essere il tassello mancante di cui abbiamo bisogno per mettere in sicurezza il resto della ⟦Valley of Bones=Valle delle Ossa⟧. Va', ora, {race}, sfruttiamo i metodi dei Gelkis prima della loro prossima scoperta.", "Solo tre? Hmmph, Warug è avaro come sempre. Dammi un momento mentre creo i bastoni.\n\nUno lo prendo io. Il secondo andrà al Necrokhan che pattuglia lungo il punto di strozzatura verso le rovine degli elfi.\n\nIl terzo è tuo. Fai parte di questa guerra, ora più che mai.", 0x79a08fa8, 0x4a5b92ad, 0x792146f7, 0x27235679, 0xaefcb3ab, "....." },
  [92849] = { "Lo studioso scomparso", "Continua a cercare Fillion Flamebreeze.", "<A giudicare da ciò che hai appena trovato, è molto probabile che a Fillion sia capitata qualche disgrazia qui. Potrebbe essere ancora nei paraggi, e potrebbe avere bisogno di aiuto. Noti una grotta appena a nord di dove ti trovi. Dovresti continuare a cercarlo lì.>", nil, "Gr... grazie, <straniero/straniera>. Stavo tornando da un incarico alle ⟦Overlook Standing Stones=Pietre Erette del Belvedere⟧ quando all'improvviso sono stato colto in un'imboscata e aggredito dai Windshaper. Mi hanno trascinato fino all'imbocco della grotta e mi hanno lasciato lì, a malapena cosciente e sanguinante. L'ultima cosa che ricordo prima di perdere i sensi è un'enorme bestia alata che usciva dalla grotta e mi afferrava.\r\n\nDirei che, se non fossi arrivat<o/a> tu, sarei diventato la cena di quella bestia e dei suoi piccoli.", 0xa1e8590e, 0x1851c7de, 0xba014091, nil, 0xc5136b37, "...m." },
  [92850] = { "Lo studioso scomparso", "Uccidi la Shriekling Matriarch nella ⟦Shriekling Den=Tana degli Strillanti⟧, poi porta la sua testa a Fillion Flamebreeze a Valanaar.", "Mi sento già molto meglio. Ho una certa abilità nelle arti arcane e siamo a breve distanza da Valanaar. Posso farcela da solo. Più importante della mia sicurezza, però, è quanto vicino a Valanaar abbiano fatto il nido questi shriekling e il pericolo che rappresentano. Se vuoi essere così gentile, torna dentro e prendi la testa di quella bestia!\r\n\nQuando avrai finito, mi troverai di nuovo a Valanaar. Devo riferire al magistro supremo ciò che è successo qui e lo stato della mia missione.", "Quegli shriekling sono troppo pericolosi per lasciarli nidificare così vicino a Valanaar. Però... sono il minore dei nostri problemi.", "Grazie ancora, {name}.", 0xa1e8590e, 0xbe3aeb06, 0x74495b96, 0xa39befbf, 0xef8e99bb, "....." },
  [92858] = { "RICERCATO: Ohk'zi", "Porta il Bastone di Ohk'zi a ⟦Latronicus Moonspear=Latronicus Lanciargentea⟧ alla Roccaforte di Piumaluna.", "Per ordine del generale Piumaluna:\n\nÈ offerta una taglia a chiunque uccida l'ogre noto come Ohk'zi. Pur non essendo una minaccia pressante come i naga, gli ogre Gordunni sono un pericolo simile per le terre di Feralas.\n\nOhk'zi è stato visto l'ultima volta all'avamposto dei Gordunni a est di qui. La ricompensa sarà consegnata dietro prova della sua morte.\n\n-- ⟦Latronicus Moonspear=Latronicus Lanciargentea⟧", nil, nil, 0x3b0e939c, 0xbdb04c54, 0x96e8f7d4, nil, nil, "...mm" },
  [92859] = { "Velo delle Terre Selvagge d'Inverno", "Porta $N1 Pelliccia di Chimera di ⟦Winterspring=Fontefredda⟧ e $N2 Piuma di ⟦Winterspring Owl=Gufo di Fontefredda⟧ a ⟦Evie Whirlbrew=Evie Giraintruglio⟧.", "Da quando è finita la guerra c'è chi cerca di salire sul ⟦Mount Hyjal=Monte Hyjal⟧, ma c'è un grosso problema... tutti i demoni nella ⟦Darkwhisper Gorge=Gola di Mormoscuro⟧!\n\nPenso di avere la soluzione. Un infuso fatto con ingredienti locali potrebbe far mimetizzare chi lo beve con l'ambiente di ⟦Winterspring=Fontefredda⟧, così che le creature qui non lo vedano così facilmente.\n\nMi piacerebbe mettere alla prova questa teoria, se te la senti di portarmi qualche piccola cosa!", nil, nil, 0xf22daeb2, 0xccb37aaf, 0x4c5725b3, nil, nil, "...mm" },
  [92860] = { "Al servizio di Zephras", "Fai rapporto a Valennia Stormfist e falle sapere che l'High Order è al loro fianco nella lotta contro gli Al'Aketh.", "L'High Order ha fatto del suo meglio per evitare uno scontro diretto con il culto, ma è chiaro che non è più possibile. La loro ostilità si è dimostrata in modo evidente, e ora girano voci di movimenti del culto su più vasta scala in tutta l'isola. Si stanno chiaramente preparando a qualcosa, e qualunque cosa sia non può essere un bene per la gente di Zephras.\r\n\nFai rapporto a Valennia Stormfist e informala che l'High Order offre il suo pieno sostegno agli sforzi di Valanaar contro gli Al'Aketh, se ce ne fosse bisogno.", nil, "Mi dispiace per Belathaan. In realtà era mio cugino, ed era un buon mago e un servitore di Zephras. Lo vendicheremo.\r\n\nSembri ansios<o/a> di dare subito una mano. Vieni, parliamo ancora della situazione attuale.", 0x81e9cbc4, 0x1fd448de, 0xae75fd2c, nil, 0xbacbd841, "...m." },
  [92867] = { "Terreno da difendere", "Sconfiggi gli intrusi Rocciadura, della ⟦Syndicate=Lega dei Tagliagole⟧ e Scorzasecca nel ⟦Stromgarde Keep=Forte di Stromgarde⟧ e torna dal giardiniere Lomar.", "La nostra eredità starà anche andando in rovina, ma questo non è il nostro ultimo baluardo. Abbiamo altro in serbo, e deve restare nascosto per la sua stessa protezione.\r\n\nCresce il sostegno alla conservazione delle nostre sculture superstiti e dei nostri sacri luoghi di sepoltura. La marmaglia che si è stabilita nel nostro antico regno non ha idea della vendetta che sta per abbattersi su di loro.\r\n\nRespingi i Rocciadura e la ⟦Syndicate=Lega dei Tagliagole⟧. Devono imparare che Stromgarde non è solo pugno, aquila e pietre.", nil, nil, 0x145549ff, 0xac3e4457, 0xf5afba33, nil, nil, "...mm" },
  [92871] = { "Al servizio di Zephras", "Fai rapporto a Valennia Stormfist e falle sapere che i Windshaper sono al loro fianco nella lotta contro gli Al'Aketh.", "Valennia Stormfist e i suoi Pacificatori sono da sempre i protettori di Zephras, e noi abbiamo fatto del nostro meglio per dare aiuto dove potevamo. Girano voci di movimenti del culto su più vasta scala in tutta l'isola, e si stanno chiaramente preparando a qualcosa.\r\n\nFai rapporto a Valennia e ribadiscile che i Windshaper offrono il loro pieno sostegno agli sforzi di Valanaar contro gli Al'Aketh, se ce ne fosse bisogno.", nil, "Sembri ansios<o/a> di dare subito una mano. Vieni, parliamo ancora della situazione attuale.", 0x81e9cbc4, 0x0b60fad2, 0x2e47c801, nil, 0xbbe87049, "...m." },
  [92872] = { "Passi devoti", "Getta il ⟦Pouch of Tomb Dust=Sacchetto di Polvere Tombale⟧ nel ⟦The Great Sea=Grande Mare⟧ e torna dal curato Alaric nella cripta del ⟦Stromgarde Keep=Forte di Stromgarde⟧.", "Custodiamo in eterno questa tomba e la conoscenza dei riti cerimoniali con cui si onorano queste anime cadute.\r\n\nOra che sei sces<o/a> tre livelli sotto terra, muovi i primi passi per tornare al mondo illuminato dal sole con una saggezza sacra.\r\n\nOgni stagione portiamo un po' della polvere di questa tomba e la spargiamo negli oceani di Azeroth. Un atto simbolico di rinnovamento dei cicli.\r\n\nPrendi questo sacchetto. Va' sulle scogliere dietro il ⟦Stromgarde Keep=Forte di Stromgarde⟧ e gettalo in mare.", nil, nil, 0xcb0fa307, 0x071c9b32, 0x760c5f39, nil, nil, "...mm" },
  [92873] = { "La prova pratica", "Mantieni la tua reputazione presso il clan Magram, poi riporta a Orgrul $N1 Well Cursed Bone da un rituale riuscito.", "Sappiamo già che questi cristalli sono capaci di ben più che spaccare il terreno: i Gelkis hanno dimostrato che si possono piegare al potere negromantico. Ti ricordi le ossa che ti ho fatto raccogliere? Le ho assemblate come meglio potevo, appena su per la collina. Ce n'erano abbastanza per due scheletri funzionanti.\r\n\n<Orgrul ti consegna un bastone appena fabbricato.>\r\n\nConsegnerò io il bastone del Necrokhan mentre tu giochi con il tuo nuovo giocattolo. Torna solo quando potrai dimostrare di saperlo usare.", "Nonostante il tuo aiuto finora, se non sei in grado di risvegliare i morti, la tua utilità presso i Magram è giunta al termine.", "Vedo un nuovo fuoco ardere nei tuoi occhi, forestiero. Hai dimostrato di saper creare le tue armi, evocare servitori che eseguano i tuoi ordini e, soprattutto, di imporre il tuo dominio quando si rifiutano di seguire i tuoi comandi.\n\nPeccato che tu non abbia sangue di centauro. Saresti sulla buona strada per diventare il prossimo Khan.", 0xf4d241cb, 0x58f13948, 0xc33d5418, 0xdfb1f611, 0x1413bf3e, "....." },
  [92878] = { "Senza parole", "Porta la prova della morte di Namida Totem Truce a Blaise Montgomery all'⟦Camp Mojache=Accampamento Mojache⟧.", "<Il Reietto indica la sua mascella inferiore mancante. Poi ti porge un foglio con un messaggio scarabocchiato in fretta.>\n\nNon posso parlare. Persa mascella in combattimento. Attaccato da Totem Truce. Guidati da druida. Namida. Accampamento a nordovest.\n\nDeve pagare.\n\n<L'ultima frase è sottolineata due volte.>", nil, nil, 0x9040e1f5, 0x1da15e1a, 0x9470fc29, nil, nil, "...mm" },
  [92880] = { "Ritorno a Valanaar", "Porta lo Yorna's Report a Valennia Stormfist a Valanaar.", "Credo che ci vorrà un po' di tempo per ripulire ciò che resta degli assalitori, ma ora le nostre possibilità sono molto migliori. Torna a Valanaar e fai sapere loro che qui la situazione è stabile.\r\n\nNon so come ringraziarti per il tuo aiuto. Senza di te saremmo messi molto peggio. Avevo chiesto rinforzi e a quanto pare ho ottenuto invece una giovane promessa tra gli eroi. Mi va bene così.\r\n\nChe i quattro venti ti benedicano, {class}.", nil, "<Valennia appare visibilmente sollevata mentre le racconti la situazione della torre di guardia orientale.>\r\n\nSiano ringraziati i venti.", 0x50dc0d7e, 0xb15128d3, 0x1556d10a, nil, 0xa8b56e05, "...m." },
  [92881] = { "La richiesta dell'alto anziano", "Parla con Talaanis Shadowsong a Valanaar.", "Gli attacchi alle torri di guardia occidentale e orientale non sono una coincidenza. Da quello che ci hai raccontato su ciò che è successo alla torre di guardia occidentale con quel sacerdote del cielo, la nostra ipotesi migliore è che il culto stia cercando di fare qualcosa ai piloni d'ancoraggio.\r\n\nParla con l'alto anziano Shadowsong. Ti parlerà di una pista che potrebbe rivelarsi promettente.", nil, "Ho una piccola faccenda che richiede proprio l'aiuto che può dare chi vive di avventure come te.", 0xb3d882cd, 0x4440ff8a, 0x4ba0a7fd, nil, 0xd03f5c14, "...m." },
  [92893] = { "Nessuna pietà per i deboli", "Mantieni la tua reputazione presso il clan Magram e uccidi $N1 Gelkis Captive sparsi per la ⟦Valley of Bones=Valle delle Ossa⟧. Torna da Orgrul una volta portato a termine il compito.", "Addentrandoti nella ⟦Valley of Bones=Valle delle Ossa⟧, troverai dei vagabondi Gelkis che hanno osato entrare nel nostro territorio. Avevo dato ordine di tenerli in vita perché nutrissero i vermi delle ossa che scavano qua e là, ma pare che a quelli non interessi che la preda sia viva.\r\n\nIl compito è semplice. Trova i prigionieri, poi spegni la loro vita. Non concedere loro nemmeno un breve barlume di speranza di libertà.", nil, "Per quanto avrei amato appendere i loro teschi alla mia tenda, i loro corpi sono molto più preziosi per i Magram rimasti nella valle.\n\nI vermi delle ossa divoreranno la loro carne entro la prossima mattina, e dopo avremo molti nuovi scheletri da risvegliare.\n\nOgni Gelkis che muore, l'esercito dei Magram diventa più forte!", 0x384f234f, 0xa451dbd7, 0x70ca071f, nil, 0x02d4fa5a, "...m." },
  [92894] = { "Ossa che risorgono", "Mantieni la tua reputazione presso il clan Magram e usa il ⟦Enhanced Necromancy Staff=Bastone Negromantico Potenziato⟧ per rianimare del tutto i non morti che faticano a emergere in tutta la ⟦Valley of Bones=Valle delle Ossa⟧. Torna da Orgrul quando l'esercito dei Magram sarà cresciuto.", "Vedo l'eccitazione nei tuoi occhi, <straniero/straniera>. Cominci a capire il potenziale della negromanzia?\r\n\nCerto che sì. Ed è per questo che ti ordino di affinare ancora le tue capacità.\r\n\nAddentrandoti nella ⟦Valley of Bones=Valle delle Ossa⟧, vedrai i resti di tentativi falliti di rianimare i morti. Tentativi dei Gelkis, senza dubbio. A malapena riescono a uscire dalla terra con gli artigli. Sarebbe divertente, se non fosse così patetico.\r\n\nHo infuso nel tuo bastone un potere più grande. Usalo per far crescere il nostro esercito e schiaccia quelli che si ribellano!", nil, "<Orgrul ascolta la tua spiegazione, incapace di trattenere un ghigno.>\n\nNon preoccuparti, forestiero, perché questo esperimento è stato tutt'altro che un fallimento. Ora sappiamo quanto sia debole e fragile la forma di negromanzia dei Gelkis. Hanno ancora molta strada da fare prima di eguagliare la nostra potenza.\n\nAnche il fatto che tu abbia preso il controllo di alcuni di loro parla bene di te. Nonostante quegli scheletri sprecati, hai dimostrato le tue notevoli capacità.\n\nPer ora prendo io il bastone. C'è ancora del lavoro da fare.", 0x2ba21978, 0x13a123ec, 0x078c77e1, nil, 0x1ad357b5, "...m." },
  [92909] = { "Mietere i mietitori", "Ozwin Ironsprocket alla ⟦Saldean's Farm=Fattoria dei Saldean⟧ vuole che tu gli porti 14 Golem Isospring e 5 Harvester Gyrostabilizer.", "Oh no... ora sono nei guai!\r\n\nHo sentito dei mietitori che terrorizzano i campi delle ⟦Westfall=Marche Occidentali⟧, così sono venuto fin da ⟦Ironforge=Forgiardente⟧ per vedere se potevo ricalibrarli. Ma sono molto più aggressivi di quanto prevedessero i miei calcoli, e mi hanno inseguito fin dentro questa stalla!\r\n\nSe avessi degli isomolle e dei girostabilizzatori dei mietitori, potrei costruire un congegno per coprirmi la fuga. Potresti raccogliere i pezzi per me?", "Là fuori è un disastro, {name}! Hai raccolto i pezzi che mi servono?", "Grazie mille! Mi metto subito al lavoro su un piano di fuga. Nel frattempo, prendi questo!", 0xced8714e, 0xb9cd3180, 0x7c112345, 0x86f9d0d9, 0x2ee3cde7, "....." },
  [92910] = { "Mietere i mietitori", "Porta l'⟦Precessive Autocognition Assembly=Assemblaggio di Autocognizione Precessiva⟧ a Ozwin Ironsprocket alla ⟦Saldean's Farm=Fattoria dei Saldean⟧.", "Il pezzo che sei riuscit<o/a> a recuperare dal mietitore sembra quasi intatto. Qualcuno interessato ai golem mietitori potrebbe volerlo vedere.", nil, nil, 0xced8714e, 0xd39b8561, 0x8ffaa4f3, nil, nil, "...mm" },
  [92911] = { "Mietere i mietitori", "Ozwin Ironsprocket alla ⟦Saldean's Farm=Fattoria dei Saldean⟧ vuole che tu gli porti 8 Golem Isospring, 4 Copper Modulator e un ⟦Crude Scope=Mirino Grezzo⟧.", "Capisco... questo mi fa capire meglio come funzionano quei mostri. Ho un'idea su come potremmo forzare i loro sistemi, almeno per un momento.\r\n\nContinuerò ad armeggiare con il congegno che mi hai portato. Nel frattempo, potresti racimolare qualche pezzo per il dispositivo?", nil, nil, 0xced8714e, 0x7ea5662a, 0xb1fbfa85, nil, nil, "...mm" },
  [92914] = { "Strani piloni", "Esplora Shen'dralas per trovare altri piloni come quello che hai trovato.", "<Ti avvicini allo strano cristallo, custodito fino a pochi istanti fa da elementali di mana emaciati.\n\nIl suo piedistallo, pur antico, è visibilmente meno fatiscente delle rovine elfiche su cui poggia.\n\nUn debole ronzio di potere emana dalla gemma fratturata, ma con la sua magia così esaurita il suo scopo resterà per ora un mistero.\n\nForse c'è altro da scoprire nei dintorni.>", nil, "Sapere che il cristallo dentro il tempio brilla di nuovo è un peso immenso tolto dalle mie spalle. Temevo che ora i centauri avessero violato anche i terreni del tempio. Sembra che continuino a essere respinti da ciò che c'è all'interno.\n\nQuanto agli altri piloni, se gli elementali vi vegliano ancora, allora si possono senz'altro ripristinare.\n\nSpero che gli abitanti del tempio non ti abbiano spaventato. Sono abbastanza amichevoli, solo amareggiati. Comprensibilmente amareggiati.", 0x20595b32, 0xa53a2c63, 0x4ac9b119, nil, 0x7bdc3281, "...m." },
  [92947] = { "Passiamo all'azione", "Uccidi $N1 Al'Aketh Guardian, $N2 Al'Aketh Spiritcaller e $N3 Al'Aketh Blademaster, poi fai rapporto a Hyusaa Quickbreeze al ⟦Shrine of Akir=Sacrario di Akir⟧.", "Ci siamo tutti, bene. Ho appena mandato alcuni dei miei migliori combattenti dall'ingresso principale del santuario per creare un po' di scompiglio e fare da diversivo, mentre io guido il grosso delle nostre forze dal fianco.\r\n\nSe tutto va bene, dovremmo riuscire a sfondare in fretta ed eliminare la somma sacerdotessa. Quanto a te, entra lì e comincia a spaccare crani. Raggiungi il mio secondo, Hyusaa Quickbreeze, vicino alla scalinata del santuario dopo aver creato un po' di scompiglio.\r\n\nChe i venti ti guidino, {class}.", "<Hyusaa ti rivolge un cenno del capo.>", "Abbiamo combattuto duramente per arrivare fin qui, ma non è ancora finita.", 0x688633bd, 0x590637a2, 0x12ee8711, 0x9c88cf2c, 0xb4531928, "....." },
  [92959] = { "Gli antichi morenti", "Dai la caccia all'antico corrotto Spaccascorza e distruggilo, poi pianta un seme tra i suoi resti.", "Questa corruzione... si insinua nei miei arti, nelle mie radici. Non sono l'unico. Anche altri Antichi... hanno sentito questa corruzione.\n\nUno dei miei più vecchi amici... Spaccascorza... la corruzione lo ha spezzato, ne ha fatto una creatura di rabbia e dolore. È... troppo tardi per salvarlo, ormai.\n\nVa' alla pozza corrotta a est... colpisci l'albero corrotto e lui verrà.\n\nPrendi questo seme... e piantalo tra i suoi resti quando l'atto sarà compiuto. Con cura... da questo dolore può ancora nascere qualcosa di buono.", nil, nil, 0xd5a1264d, 0x7ab45951, 0x79260c27, nil, nil, "...mm" },
  [92960] = { "Essenza Effimera prosciugata", "Recupera $N1 Essenza Effimera per Elaena Sussurraluna.", "Una persistente presenza demoniaca rimane a est. Tra loro ci sono le bestie infernali responsabili di aver devastato i nostri simili, risucchiandone il potere per usarlo contro i nostri alleati.\n\nPenetra nel loro accampamento, individua queste bestie e uccidile. Recupera ogni campione che resta.\n\nForse c'è qualcosa che possiamo imparare da questi sforzi.", nil, nil, 0x0deaf629, 0x72504ce3, 0x0538a40d, nil, nil, "...mm" },
})
